function useAuthHeaders() {
  const { getToken } = useAuth();
  return useCallback(async (): Promise<HeadersInit> => {
    const token = await getToken();
    return token ? { Authorization: `Bearer ${token}` } : {};
  }, [getToken]);
}

function DarkToggle({ size = 44 }: { size?: number }) {
  const { dark, toggle } = useDark();
  return (
    <button
      onClick={toggle}
      aria-label={dark ? 'Mode clair' : 'Mode sombre'}
      className="rounded-full flex items-center justify-center font-black transition-all active:scale-90 hover:scale-110"
      style={{
        background: 'var(--c-card)', border: '2.5px solid #D9C5A0',
        color: '#065F46', boxShadow: '0 4px 20px rgba(6,95,70,0.15)',
        height: size, width: size, fontSize: size * 0.42,
      }}>
      {dark ? '☀️' : '🌙'}
    </button>
  );
}

// ─── DELIVERY ZONE ────────────────────────────────────────────────────────────

// Zone elargie le 2026-07-10 (x1.3 depuis le centre) suite a un signalement
// zabi : des adresses bien reelles et centrales de Safi (ex: quartier Achbar,
// Achbar Allal) tombaient hors de l'ancien polygone trop serre et se
// faisaient rejeter a tort ("zone non couverte") au clic "Ma position GPS".
// 2026-07-10 (2e passe) : le polygone serre continuait a rejeter des adresses
// reelles de Safi (Achbar Allal etc) a chaque nouveau test de zabi. Remplace
// par un grand rectangle couvrant tout le Grand Safi (mer a l'ouest jusqu'a
// la peripherie est) pour arreter les faux "zone non couverte". On garde un
// polygone (pas juste un bounding-box) pour pouvoir affiner plus tard si
// besoin, mais les coins sont volontairement tres larges pour l'instant.
const DELIVERY_ZONE: [number,number][] = [
  [32.365,-9.30],  // nord-ouest (large marge cote/ocean)
  [32.365,-9.12],  // nord-est
  [32.16,-9.12],   // sud-est
  [32.16,-9.30],   // sud-ouest
];

function pointInPolygon(lat:number, lng:number, poly:[number,number][]): boolean {
  let inside=false;
  for(let i=0,j=poly.length-1;i<poly.length;j=i++){
    const [xi,yi]=poly[i]; const [xj,yj]=poly[j];
    if(((yi>lng)!==(yj>lng))&&(lat<(xj-xi)*(lng-yi)/(yj-yi)+xi)) inside=!inside;
  }
  return inside;
}

const clientPinIcon = L.divIcon({
  className:'',
  html:`<div style="width:32px;height:32px;border-radius:50%;background:#4F46E5;border:3px solid #fff;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 14px rgba(79,70,229,0.5);font-size:15px;">📍</div>`,
  iconSize:[32,32],iconAnchor:[16,16],
});

function MapClickLayer({onPick}:{onPick:(lat:number,lng:number,inside:boolean)=>void}) {
  useMapEvents({
    click(e){
      const inside=pointInPolygon(e.latlng.lat,e.latlng.lng,DELIVERY_ZONE);
      onPick(e.latlng.lat,e.latlng.lng,inside);
    }
  });
  return null;
}

// Reverse geocoding via Nominatim — returns a short readable address
async function reverseGeocode(lat:number,lng:number):Promise<string> {
  try {
    const res=await fetch(
      `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json&accept-language=fr`,
      {headers:{'User-Agent':'BridgeSafi/1.0'}}
    );
    if(!res.ok) return '';
    const d=await res.json();
    const a=d.address||{};
    const parts=[
      a.house_number,
      a.road||a.pedestrian||a.footway||a.path,
      a.neighbourhood||a.suburb||a.quarter||a.city_district,
    ].filter(Boolean);
    return parts.length>=2 ? parts.join(' ') : (d.display_name||'').split(',').slice(0,2).join(',').trim();
  } catch(_){return '';}
}

// Draggable pin marker — updates when dragged
function DraggablePin({pos,onDragEnd}:{pos:[number,number];onDragEnd:(lat:number,lng:number)=>void}) {
  const markerRef=useRef<L.Marker|null>(null);
  return (
    <Marker
      position={pos}
      icon={clientPinIcon}
      draggable
      ref={markerRef}
      eventHandlers={{
        dragend(){
          const m=markerRef.current;
          if(m){const {lat,lng}=m.getLatLng();onDragEnd(lat,lng);}
        }
      }}
    />
  );
}

function DeliveryMap({onSet,onAddress,pin,lang='fr'}:{
  onSet:(coords:string,inside:boolean)=>void;
  onAddress:(addr:string)=>void;
  pin:[number,number]|null;
  lang?:Lang;
}) {
  const t=T[lang];
  const [geocoding,setGeocoding]=useState(false);
  const [gettingGPS,setGettingGPS]=useState(false);

  const handlePick=async(lat:number,lng:number)=>{
    const inside=pointInPolygon(lat,lng,DELIVERY_ZONE);
    onSet(`${lat.toFixed(5)},${lng.toFixed(5)}`,inside);
    setGeocoding(true);
    const addr=await reverseGeocode(lat,lng);
    setGeocoding(false);
    if(addr) onAddress(addr);
  };

  const useMyGPS=()=>{
    if(!navigator.geolocation){return;}
    setGettingGPS(true);
    navigator.geolocation.getCurrentPosition(
      pos=>{handlePick(pos.coords.latitude,pos.coords.longitude).finally(()=>setGettingGPS(false));},
      ()=>setGettingGPS(false),
      {enableHighAccuracy:true,timeout:8000}
    );
  };

  return (
    <div className="relative mb-3">
      <MapContainer center={[32.2994,-9.2372]} zoom={13}
        style={{height:220,borderRadius:14,zIndex:0}} scrollWheelZoom={false}
        maxBounds={[[32.16,-9.30],[32.365,-9.12]]} maxBoundsViscosity={1.0} minZoom={12}>
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution='&copy; <a href="https://osm.org">OpenStreetMap</a>'/>
        <Polygon positions={DELIVERY_ZONE} pathOptions={{color:'#065F46',fillColor:'#2ecc71',fillOpacity:0.18,weight:2,dashArray:'6,4'}}/>
        <MapClickLayer onPick={handlePick}/>
        {pin&&<DraggablePin pos={pin} onDragEnd={handlePick}/>}
      </MapContainer>
      <button type="button" onClick={useMyGPS} disabled={gettingGPS}
        style={{position:'absolute',top:8,right:8,zIndex:1000,padding:'7px 11px',borderRadius:10,border:'none',
          background:gettingGPS?'rgba(6,95,70,0.6)':'#065F46',color:'#fff',fontWeight:900,fontSize:11,
          cursor:gettingGPS?'not-allowed':'pointer',display:'flex',alignItems:'center',gap:5,boxShadow:'0 3px 10px rgba(0,0,0,0.3)'}}>
        {gettingGPS?<span style={{animation:'spin 1s linear infinite',display:'inline-block'}}>⟳</span>:<span>🎯</span>}
        {gettingGPS?t.gpsDetecting:t.gpsMyPosition}
      </button>
      {geocoding&&(
        <div className="absolute bottom-2 left-1/2 -translate-x-1/2 px-3 py-1 rounded-full text-[10px] font-bold text-white flex items-center gap-1.5"
          style={{background:'rgba(6,95,70,0.85)',backdropFilter:'blur(4px)',zIndex:1000}}>
          <span className="w-2 h-2 rounded-full bg-green-300 animate-pulse"/>
          {t.addressLoading}
        </div>
      )}
    </div>
  );
}

