function MedItem({med,qty,isNight,nightSurcharge,effectivePrice,onAdd,onRem}:{med:MedEntry;qty:number;isNight:boolean;nightSurcharge:number;effectivePrice:number;onAdd:()=>void;onRem:()=>void}) {
  const [imgOk,setImgOk]=useState(!!med.img);
  return(
    <div className="flex flex-col gap-2 rounded-2xl p-3"
      style={{background:qty>0?'rgba(99,102,241,0.18)':'rgba(255,255,255,0.04)',border:`1.5px solid ${qty>0?'rgba(99,102,241,0.5)':'rgba(165,180,252,0.15)'}`,transition:'all 0.15s'}}>
      <div style={{width:'100%',height:108,borderRadius:12,flexShrink:0,overflow:'hidden',boxShadow:'0 2px 10px rgba(0,0,0,0.35)'}}>
        {med.img&&imgOk?(
          <img src={med.img} alt={med.name} onError={()=>setImgOk(false)} style={{width:'100%',height:'100%',objectFit:'cover'}}/>
        ):(
          <div style={{width:'100%',height:'100%',background:'rgba(99,102,241,0.25)',border:'1px solid rgba(165,180,252,0.25)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:36}}>
            {med.emoji}
          </div>
        )}
      </div>
      <div style={{minWidth:0}}>
        <p className="font-black text-[14px] leading-tight" style={{color:'#E0E7FF'}}>{med.name}</p>
        <p className="text-[11px] mt-0.5" style={{color:'rgba(165,180,252,0.55)',display:'-webkit-box',WebkitLineClamp:2,WebkitBoxOrient:'vertical',overflow:'hidden'}}>{med.desc}</p>
        <div className="flex items-center gap-1.5 mt-1 flex-wrap">
          <span className="text-[13px] font-black" style={{color:'#A5B4FC'}}>{effectivePrice} DH</span>
          {isNight&&<span style={{background:'rgba(251,191,36,0.15)',border:'1px solid rgba(251,191,36,0.4)',borderRadius:4,padding:'0 4px',fontSize:9,color:'#F59E0B',fontWeight:700}}>🌙 +{nightSurcharge}</span>}
        </div>
      </div>
      <div className="flex items-center justify-end gap-2 flex-shrink-0 mt-auto">
        {qty>0&&(
          <>
            <button onClick={onRem} style={{width:32,height:32,borderRadius:'50%',border:'none',background:'rgba(99,102,241,0.25)',color:'#A5B4FC',fontWeight:900,fontSize:18,cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center'}}>−</button>
            <span className="font-black text-base w-5 text-center" style={{color:'#fff'}}>{qty}</span>
          </>
        )}
        <button onClick={onAdd} style={{width:32,height:32,borderRadius:'50%',border:'none',background:'#6366F1',color:'white',fontWeight:900,fontSize:18,cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center'}}>+</button>
      </div>
    </div>
  );
}

function PharmaciePage({onBack,lang,cycleLang,profile,saveProfile,onOrderSuccess}:{onBack:()=>void;lang:Lang;cycleLang:()=>void;profile:UserProfile;saveProfile:(p:UserProfile)=>void;onOrderSuccess?:(ref:string)=>void}) {
  const { user } = useUser();
  const fClass=fontClass(lang); const isAR=lang==='ar';
  const [,navigatePharm]=useLocation();

  // ── Night ──
  const nowH=new Date().getHours();
  const isNight=nowH>=22||nowH<6;
  const NIGHT_SURCHARGE=10; // DH par médicament la nuit
  const DELIV_FEE_PHARM=(isNight?18:12);
  const SVC_FEE_PHARM=6.5;

  // ── State ──
  const [pharmCart,setPharmCart]=useState<{id:string;qty:number}[]>([]);
  const [pharmCat,setPharmCat]=useState<MedEntry['cat']>('douleur');
  const [pharmSearch,setPharmSearch]=useState('');
  const [delivMode,setDelivMode]=useState<'delivery'|'collect'>('delivery');
  const [name,setName]=useState(profile.name??'');
  const [addr,setAddr]=useState(profile.address??'');
  const [phone,setPhone]=useState(profile.phone??'');
  const [err,setErr]=useState('');
  const [sending,setSending]=useState(false);
  const [sent,setSent]=useState(false);
  const [orderRef]=useState(()=>`PH-${Math.floor(1000+Math.random()*9000)}`);
  const [payMethod,setPayMethod]=useState<PayMethodType>(null);
  const [paypalEmail,setPaypalEmail]=useState(profile.paypalEmail||'');
  const [showQR,setShowQR]=useState(false);
  const {user:pharmUser}=useUser();
  const getAuthHeadersPharm=useAuthHeaders();
  const [pharmGems,setPharmGems]=useState(0);
  const [pharmGemMAD,setPharmGemMAD]=useState(0);
  const maxPharmGemMAD=Math.floor(pharmGems/200);

  useEffect(()=>{
    if(!pharmUser?.id) return;
    getAuthHeadersPharm().then(h=>fetch('/api/game/diamonds',{credentials:'include',headers:h})
      .then(r=>r.ok?r.json():null)
      .then(d=>{if(d&&typeof d.diamonds==='number')setPharmGems(d.diamonds);})
      .catch(()=>{}));
  },[pharmUser?.id,getAuthHeadersPharm]);

  // ── Cart helpers ──
  const addMed=(id:string)=>setPharmCart(c=>{const ex=c.find(x=>x.id===id);return ex?c.map(x=>x.id===id?{...x,qty:x.qty+1}:x):[...c,{id,qty:1}];});
  const remMed=(id:string)=>setPharmCart(c=>{const ex=c.find(x=>x.id===id);if(!ex)return c;if(ex.qty===1)return c.filter(x=>x.id!==id);return c.map(x=>x.id===id?{...x,qty:x.qty-1}:x);});
  const medQty=(id:string)=>pharmCart.find(x=>x.id===id)?.qty??0;
  const medPrice=(m:MedEntry)=>m.price+(isNight?NIGHT_SURCHARGE:0);
  const cartSubtotal=pharmCart.reduce((s,ci)=>{const m=PHARMA_CATALOG.find(f=>f.id===ci.id);return s+(m?medPrice(m)*ci.qty:0);},0);
  const cartTotal=cartSubtotal+DELIV_FEE_PHARM+SVC_FEE_PHARM-pharmGemMAD;
  const cartCount=pharmCart.reduce((s,ci)=>s+ci.qty,0);

  const visibleMeds=PHARMA_CATALOG.filter(m=>
    m.cat===pharmCat&&(pharmSearch===''||m.name.toLowerCase().includes(pharmSearch.toLowerCase()))
  );

  const catTabs:{key:MedEntry['cat'];label:string;emoji:string}[]=[
    {key:'douleur',   label:lang==='ar'?'ألم':lang==='en'?'Pain':'Douleur',     emoji:'💊'},
    {key:'digestif',  label:lang==='ar'?'هضم':lang==='en'?'Digestive':'Digestif', emoji:'🤢'},
    {key:'rhume',     label:lang==='ar'?'زكام':lang==='en'?'Cold':'Rhume',       emoji:'🤧'},
    {key:'peau',      label:lang==='ar'?'جلد':lang==='en'?'Skin':'Peau',         emoji:'🩹'},
    {key:'vitamines', label:lang==='ar'?'فيتامين':lang==='en'?'Vitamins':'Vitamines', emoji:'💛'},
    {key:'yeux',      label:lang==='ar'?'عيون':lang==='en'?'Eyes':'Yeux',        emoji:'👁️'},
    {key:'parapharmacie', label:lang==='ar'?'شبه صيدلية':lang==='en'?'Parapharmacy':'Parapharmacie', emoji:'🧴'},
  ];

  const inputCls=`w-full px-4 py-3 rounded-xl text-sm font-medium outline-none transition-all ${fClass}`;
  const inputStyle=(hasErr:boolean):React.CSSProperties=>({background:'rgba(255,255,255,0.07)',border:`1.5px solid ${hasErr?'#EF4444':'rgba(165,180,252,0.2)'}`,color:'#fff'});

  const handleWalletPay=async(type:'apple'|'google')=>{
    if(!name.trim()||!phone.trim()||(delivMode==='delivery'&&!addr.trim())){setErr('*');return;}
    const payLabel=type==='apple'?'Apple Pay':'Google Pay';
    const methods=type==='apple'
      ?[{supportedMethods:'https://apple.com/apple-pay',data:{version:3,merchantIdentifier:'merchant.ma.safi-bridge',merchantCapabilities:['supports3DS'],supportedNetworks:['visa','masterCard'],countryCode:'MA'}}]
      :[{supportedMethods:'https://google.com/pay',data:{apiVersion:2,apiVersionMinor:0,merchantInfo:{merchantName:'Bridge Safi'},allowedPaymentMethods:[{type:'CARD',parameters:{allowedAuthMethods:['PAN_ONLY','CRYPTOGRAM_3DS'],allowedCardNetworks:['MASTERCARD','VISA']},tokenizationSpecification:{type:'PAYMENT_GATEWAY',parameters:{gateway:'example',gatewayMerchantId:'bridge-safi'}}}]}}];
    const details={total:{label:'Bridge Pharmacie · Safi',amount:{currency:'MAD',value:String(cartTotal)}}};
    try{
      if(typeof PaymentRequest==='undefined') throw new Error('unsupported');
      const pr=new PaymentRequest(methods,details);
      const canMake=await pr.canMakePayment().catch(()=>false);
      if(!canMake) throw new Error('unavailable');
      const response=await pr.show();
      await response.complete('success');
      setPayMethod(type);
      await handleSend(payLabel);
    }catch{setPayMethod('cash');}
  };

  const handleSend=async(payLabel?:string)=>{
    if(!name.trim()||!phone.trim()||(delivMode==='delivery'&&!addr.trim())){setErr('*');return;}
    setSending(true);
    const deliveryAddress=delivMode==='delivery'?`${addr.trim()}, Safi, Maroc`:'Pharmacie Bridge Safi — Retrait sur place';
    const driverTrackUrl=`${window.location.origin}/driver/${orderRef}`;
    const payInfo=payLabel?payLabel:payMethod==='qr'?'QR Code':payMethod==='cash'?'Espèces':payMethod==='apple'?'Apple Pay':payMethod==='google'?'Google Pay':payMethod==='paypal'?'PayPal'+(paypalEmail?' · '+paypalEmail:''):'Espèces';
    const itemsList=pharmCart.map(ci=>{const m=PHARMA_CATALOG.find(f=>f.id===ci.id)!;const ep=medPrice(m);return `${m.name} ×${ci.qty} (${ep*ci.qty} DH${isNight?' 🌙':''})`;}).join('\n');
    const notesStr=`💊 Bridge Pharmacie${isNight?' 🌙 NUIT':''}\n${itemsList||'Commande générale'}\n—\nSous-total: ${cartSubtotal} DH\nLivraison: ${DELIV_FEE_PHARM} DH${isNight?' (tarif nuit)':''}\nService: ${SVC_FEE_PHARM} DH\nTotal: ${cartTotal} DH\n💳 ${payInfo}\n👤 ${name.trim()} — ${phone.trim()}`;
    const apiItems=pharmCart.length>0
      ?pharmCart.map(ci=>{const m=PHARMA_CATALOG.find(f=>f.id===ci.id)!;return {name:m.name,qty:ci.qty,price:medPrice(m)};})
      :[{name:'💊 Commande Bridge Pharmacie',qty:1,price:0}];
    try{
      await fetch('/api/orders/inbound',{method:'POST',headers:{'Content-Type':'application/json','x-bridge-secret':'bridge-safi-8b269bba03fd8c0205116f3f'},
        body:JSON.stringify({customerName:name.trim(),customerPhone:phone.trim(),deliveryAddress,pickupAddress:'Bridge Pharmacie — Safi',items:apiItems,total:cartTotal,source:'Bridge Pharmacie',paymentMethod:payInfo}),
      }).catch(()=>{});
      await fetch(`${DRIVER_APP_URL}/api/deliveries`,{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({trackingNumber:orderRef,customerName:name.trim(),customerPhone:phone.trim(),pickupAddress:'Pharmacie Bridge Safi',deliveryAddress,priority:'normal',notes:notesStr,driverTrackUrl}),
      }).catch(()=>{});
    }finally{setSending(false);}
    if(pharmGemMAD>0){getAuthHeadersPharm().then(h=>fetch('/api/game/diamonds/spend',{method:'POST',credentials:'include',headers:{...h,'Content-Type':'application/json'},body:JSON.stringify({spend:pharmGemMAD*200})}).then(r=>r.ok?r.json():null).then(d=>{if(d&&typeof d.diamonds==='number'){const ck=`bridge_diamonds_cache_${pharmUser?.id||'anon'}`;try{localStorage.setItem(ck,String(d.diamonds));}catch{}window.dispatchEvent(new StorageEvent('storage',{key:ck,newValue:String(d.diamonds)}));}}).catch(()=>{}));}
    await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({ref:orderRef,service:'pharmacie',customerName:name.trim(),customerPhone:phone.trim(),customerAddress:deliveryAddress,items:apiItems,total:cartTotal,deliveryMode:delivMode,paymentMethod:payInfo,restaurantName:'Bridge Pharmacie'}),
    }).catch(()=>{});
    fetch(`/api/tracking/${orderRef}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:'shop',shopName:'Bridge Pharmacie',shopEmoji:'💊',clientAddress:deliveryAddress})}).catch(()=>{});
    localStorage.setItem('bridge_last_ref',orderRef);
    try{const raw=localStorage.getItem('bridge_history');const arr=raw?JSON.parse(raw):[];arr.unshift({ref:orderRef,type:'pharmacie',date:new Date().toISOString(),total:cartTotal,address:deliveryAddress,name:name.trim(),owner:user?.id||'guest'});if(arr.length>1000)arr.splice(1000);localStorage.setItem('bridge_history',JSON.stringify(arr));}catch{}
    setSent(true);
  };

  return(
    <div className={`min-h-screen flex flex-col ${isAR?'rtl':'ltr'}`}
      dir={isAR?'rtl':'ltr'}
      style={{background:'linear-gradient(160deg,#060818 0%,#0C0E2B 40%,#1E1B4B 70%,#0F172A 100%)',color:'#fff',minHeight:'100dvh'}}>

      {/* Header */}
      <div style={{position:'fixed',top:16,left:isAR?'auto':16,right:isAR?16:'auto',zIndex:50}}>
        <button onClick={onBack} style={{width:38,height:38,borderRadius:'50%',border:'none',cursor:'pointer',background:'rgba(165,180,252,0.12)',backdropFilter:'blur(8px)',display:'flex',alignItems:'center',justifyContent:'center',color:'#fff',fontSize:18}}>←</button>
      </div>
      <div style={{position:'fixed',top:16,right:isAR?'auto':16,left:isAR?16:'auto',zIndex:50,display:'flex',alignItems:'center',gap:8}}>
        <button onClick={cycleLang} style={{width:38,height:38,borderRadius:'50%',border:'none',cursor:'pointer',background:'rgba(165,180,252,0.18)',backdropFilter:'blur(8px)',display:'flex',alignItems:'center',justifyContent:'center',color:'#A5B4FC',fontSize:11,fontWeight:900}}>{LANG_LABELS[lang]}</button>
        <SharkDiamondWidget onNavigate={()=>navigatePharm('/game')} profile={profile} lang={lang} saveProfile={saveProfile}/>
      </div>
      <div style={{position:'fixed',top:12,left:'50%',transform:'translateX(-50%)',zIndex:49,display:'flex',alignItems:'center',gap:8,pointerEvents:'none'}}>
        <img src="/bridge_logo_nobg.png" alt="Bridge" style={{width:56,height:56,objectFit:'contain',filter:'drop-shadow(0 2px 8px rgba(165,180,252,0.5))'}}/>
      </div>

      {/* Content */}
      <div className={`flex flex-col items-center px-5 pt-20 pb-12 max-w-2xl mx-auto w-full gap-4 ${fClass}`}>

        {/* Title */}
        <div className="text-center">
          <h1 className={`font-black text-xl tracking-wider mb-0.5 ${fClass}`} style={{color:'#A5B4FC'}}>BRIDGE PHARMACIE</h1>
          <p className="text-[10px] tracking-widest font-bold" style={{color:'rgba(165,180,252,0.6)'}}>SAFI · MAROC · آسفي · ⵙⴰⴼⵉ</p>
          {isNight&&<div style={{display:'inline-flex',alignItems:'center',gap:5,background:'rgba(99,102,241,0.2)',border:'1px solid rgba(165,180,252,0.35)',borderRadius:50,padding:'3px 12px',marginTop:6}}>
            <span style={{fontSize:12}}>🌙</span>
            <span style={{color:'#C7D2FE',fontSize:10,fontWeight:900,letterSpacing:'0.12em'}}>TARIF NUIT +{NIGHT_SURCHARGE} DH/méd.</span>
          </div>}
        </div>

        {/* ── Catalogue ── */}
        {!sent&&(
          <div className="w-full">
            {/* Search */}
            <input value={pharmSearch} onChange={e=>setPharmSearch(e.target.value)}
              placeholder={lang==='ar'?'بحث دواء…':lang==='en'?'Search medication…':'Rechercher un médicament…'}
              className={`w-full px-4 py-2.5 rounded-xl text-sm outline-none mb-3 ${fClass}`}
              style={{background:'rgba(165,180,252,0.1)',border:'1.5px solid rgba(165,180,252,0.2)',color:'#fff'}}/>

            {/* Category tabs — horizontal scroll */}
            <div className="flex gap-1.5 mb-3 overflow-x-auto pb-1" style={{scrollbarWidth:'none'}}>
              {catTabs.map(tab=>(
                <button key={tab.key} onClick={()=>{setPharmCat(tab.key);setPharmSearch('');}}
                  className="flex-shrink-0 py-2 px-3 rounded-xl font-black text-[10px] transition-all active:scale-95"
                  style={{background:pharmCat===tab.key?'#6366F1':'rgba(165,180,252,0.1)',color:pharmCat===tab.key?'white':'rgba(165,180,252,0.6)',border:`1.5px solid ${pharmCat===tab.key?'#6366F1':'rgba(165,180,252,0.2)'}`,letterSpacing:'0.04em',whiteSpace:'nowrap'}}>
                  {tab.emoji} {tab.label}
                </button>
              ))}
            </div>

            {/* Items grid — 2 par ligne */}
            <div className="grid grid-cols-2 gap-2.5">
              {visibleMeds.map(med=>(
                <MedItem key={med.id} med={med} qty={medQty(med.id)} isNight={isNight} nightSurcharge={NIGHT_SURCHARGE} effectivePrice={medPrice(med)} onAdd={()=>addMed(med.id)} onRem={()=>remMed(med.id)}/>
              ))}
            </div>

            {/* Cart mini summary */}
            {cartCount>0&&(
              <div className="mt-3 rounded-2xl p-3" style={{background:'rgba(99,102,241,0.15)',border:'1.5px solid rgba(99,102,241,0.4)'}}>
                <p className="font-black text-[11px] mb-1.5" style={{color:'#A5B4FC'}}>🛒 {cartCount} {lang==='ar'?'منتج':lang==='en'?'item(s)':'produit(s)'} sélectionné(s)</p>
                {pharmCart.map(ci=>{const m=PHARMA_CATALOG.find(f=>f.id===ci.id)!;const ep=medPrice(m);return(
                  <div key={ci.id} className="flex justify-between text-[11px]" style={{color:'rgba(165,180,252,0.7)'}}>
                    <span>{m.name} ×{ci.qty}</span><span className="font-bold">{ep*ci.qty} DH</span>
                  </div>
                );})}
              </div>
            )}
          </div>
        )}

        {/* Mode selector */}
        {!sent&&(
          <div className="flex gap-2 w-full">
            {([
              {key:'delivery'as const,label:lang==='ar'?'توصيل':lang==='en'?'Delivery':'Livraison',desc:lang==='ar'?'إلى بابك':lang==='en'?'To your door':'À votre porte',color:'#6366F1'},
              {key:'collect'as const,label:lang==='ar'?'استلام':lang==='en'?'Collect':'Retrait',desc:lang==='ar'?'من الصيدلية':lang==='en'?'From pharmacy':'De la pharmacie',color:'#8B5CF6'},
            ]).map(opt=>{
              const sel=delivMode===opt.key;
              return(
                <button key={opt.key} onClick={()=>{setDelivMode(opt.key);setErr('');}}
                  className="flex-1 rounded-2xl p-3 text-left transition-all duration-200 active:scale-95"
                  style={{background:sel?'rgba(99,102,241,0.2)':'rgba(255,255,255,0.04)',border:`2px solid ${sel?opt.color:'rgba(165,180,252,0.15)'}`}}>
                  <p className={`font-black text-[11px] leading-tight ${fClass}`} style={{color:opt.color}}>{opt.label}</p>
                  <p className={`text-[9px] mt-0.5 ${fClass}`} style={{color:'rgba(165,180,252,0.4)'}}>{opt.desc}</p>
                  {sel&&<div className="mt-1.5 w-3 h-3 rounded-full flex items-center justify-center" style={{background:opt.color}}>
                    <svg width="7" height="7" viewBox="0 0 10 10" fill="white"><path d="M1.5 5l2.5 2.5 4.5-4.5" stroke="white" strokeWidth="1.8" fill="none" strokeLinecap="round"/></svg>
                  </div>}
                </button>
              );
            })}
          </div>
        )}

        {/* Form */}
        {!sent&&(
          <div className="w-full flex flex-col gap-3">
            <div>
              <p className={`text-[10px] font-black uppercase tracking-widest mb-1.5 ${fClass}`} style={{color:'#A5B4FC'}}>👤 {lang==='ar'?'الاسم':lang==='en'?'Name':'Nom'}</p>
              <input className={inputCls} style={inputStyle(!!err&&!name.trim())} placeholder={lang==='ar'?'اسمك الكامل…':lang==='en'?'Your name…':'Votre nom…'} value={name} onChange={e=>{setName(e.target.value);setErr('');}}/>
            </div>
            {delivMode==='delivery'&&(
              <AddressAutocomplete label={`📍 ${lang==='ar'?'العنوان':lang==='en'?'Address':'Adresse'}`} value={addr} onChange={v=>{setAddr(v);setErr('');}}
                placeholder={lang==='ar'?'عنوان التوصيل…':lang==='en'?'Delivery address…':'Adresse de livraison…'} lang={lang} error={!!err&&!addr.trim()}/>
            )}
            <div>
              <p className={`text-[10px] font-black uppercase tracking-widest mb-1.5 ${fClass}`} style={{color:'#A5B4FC'}}>📞 {lang==='ar'?'الهاتف':lang==='en'?'Phone':'Téléphone'}</p>
              <input className={inputCls} style={inputStyle(!!err&&!phone.trim())} placeholder="06XXXXXXXX" value={phone} type="tel" onChange={e=>{setPhone(e.target.value);setErr('');}}/>
            </div>
            {err&&<p className={`text-xs font-bold ${fClass}`} style={{color:'#EF4444'}}>⚠️ {lang==='ar'?'يرجى ملء جميع الحقول':lang==='en'?'Please fill all fields':'Veuillez remplir tous les champs'}</p>}
          </div>
        )}

        {/* Success + suivi GPS intégré */}
        {sent&&(
          <ServiceTrackingView orderRef={orderRef} lang={lang} onNewOrder={onBack}
            theme={{emoji:'💊',label:'Bridge Pharmacie',accent:'#6366F1',accentDark:'#4338CA',accentLight:'#A5B4FC',cardBg:'rgba(99,102,241,0.15)',cardBorder:'rgba(99,102,241,0.5)',textColor:'#fff',mutedColor:'rgba(165,180,252,0.6)'}}/>
        )}

        {/* Order summary */}
        {!sent&&cartCount>0&&(
          <div className="w-full rounded-2xl p-4" style={{background:'rgba(255,255,255,0.04)',border:'1.5px solid rgba(165,180,252,0.15)'}}>
            <p className={`text-[10px] font-black uppercase tracking-widest mb-3 ${fClass}`} style={{color:'#A5B4FC'}}>🧾 {lang==='ar'?'الفاتورة':lang==='en'?'Summary':'Récapitulatif'}</p>
            {cartSubtotal>0&&<div className="flex justify-between text-[12px] mb-1.5"><span style={{color:'rgba(165,180,252,0.5)'}}>{lang==='ar'?'المجموع':lang==='en'?'Subtotal':'Sous-total'}</span><span className="font-bold" style={{color:'#E0E7FF'}}>{cartSubtotal} DH</span></div>}
            {delivMode==='delivery'&&<div className="flex justify-between text-[12px] mb-1.5"><span style={{color:'rgba(165,180,252,0.5)'}}>🛵 {lang==='ar'?'توصيل':lang==='en'?'Delivery':'Livraison'}{isNight&&<span style={{color:'#F59E0B',fontWeight:700}}> 🌙</span>}</span><span className="font-bold" style={{color:'#A5B4FC'}}>{DELIV_FEE_PHARM} DH</span></div>}
            <div className="flex justify-between text-[12px] mb-2"><span style={{color:'rgba(165,180,252,0.5)'}}>⚙️ {lang==='ar'?'رسوم الخدمة':lang==='en'?'Service fee':'Frais de service'}</span><span className="font-bold" style={{color:'#A5B4FC'}}>{SVC_FEE_PHARM} DH</span></div>
            {pharmGemMAD>0&&<div className="flex justify-between text-[12px] mb-2"><span style={{color:'#4ADE80'}}>{T[lang].discountLabel}</span><span className="font-bold" style={{color:'#4ADE80'}}>-{pharmGemMAD} DH</span></div>}
            <div className="flex justify-between items-center pt-2" style={{borderTop:'1.5px solid rgba(165,180,252,0.15)'}}><span className="font-black text-sm" style={{color:'#E0E7FF'}}>TOTAL</span><span className="font-black text-lg" style={{color:'#818CF8'}}>{cartTotal} DH</span></div>
          </div>
        )}

        {/* 💎 Diamonds */}
        {!sent&&(
          <div className={`w-full rounded-2xl p-4 ${fClass}`} style={{background:'linear-gradient(135deg,#0A1A12,#0D2E1A)',border:'1px solid rgba(74,222,128,0.3)'}}>
            <p className="text-[11px] font-black mb-1.5" style={{color:'#D9C5A0'}}>💎 {lang==='ar'?'خصم بالماسات':lang==='en'?'Diamond discount':'Réduction Diamants'}</p>
            {pharmGems>0?(
              <>
                <p className="text-[10px] mb-2" style={{color:'rgba(255,255,255,0.6)',fontWeight:600}}>{pharmGems.toLocaleString()} 💎 = {maxPharmGemMAD} MAD</p>
                {pharmGemMAD>0?(
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-bold" style={{color:'#4ADE80'}}>✓ -{pharmGemMAD} MAD appliqué</span>
                    <button onClick={()=>setPharmGemMAD(0)} className="text-[9px] font-bold px-2 py-1 rounded-lg" style={{background:'rgba(255,255,255,0.1)',color:'rgba(255,255,255,0.5)',border:'none',cursor:'pointer'}}>✕</button>
                  </div>
                ):(
                  <div className="flex gap-2 flex-wrap">
                    {[1,2,5,maxPharmGemMAD].filter((v,i,a)=>v>0&&a.indexOf(v)===i&&v<=maxPharmGemMAD).map(mad=>(
                      <button key={mad} onClick={()=>setPharmGemMAD(mad)} className="px-3 py-1 rounded-xl font-black text-[10px] active:scale-95 transition-all"
                        style={{background:'rgba(74,222,128,0.2)',border:'1px solid rgba(74,222,128,0.5)',color:'#4ADE80',cursor:'pointer'}}>
                        -{mad} MAD
                      </button>
                    ))}
                  </div>
                )}
              </>
            ):(
              <div className="flex items-center justify-between gap-2">
                <p className="text-[10px]" style={{color:'rgba(255,255,255,0.4)'}}>{lang==='ar'?'لا ماسات — العب لتربح!':lang==='en'?'No diamonds — play to earn!':'Pas de diamants — jouez !'}</p>
                <button onClick={()=>navigatePharm('/game')} className="text-[9px] font-black px-2.5 py-1 rounded-xl" style={{background:'rgba(74,222,128,0.2)',border:'1px solid rgba(74,222,128,0.4)',color:'#4ADE80',cursor:'pointer',flexShrink:0}}>🎮 Game</button>
              </div>
            )}
          </div>
        )}

        {/* Payment */}
        {!sent&&(
          <div className="w-full rounded-2xl p-4" style={{background:'rgba(255,255,255,0.04)',border:'1.5px solid rgba(165,180,252,0.15)'}}>
            <p className={`text-[10px] font-black uppercase tracking-widest mb-3 ${fClass}`} style={{color:'#A5B4FC'}}>💳 {lang==='ar'?'طريقة الدفع':lang==='en'?'Payment':'Mode de paiement'}</p>
            <SharedPaymentOptions lang={lang} selected={payMethod} onSelect={setPayMethod} showCash showCard={false} paypalEmail={paypalEmail} onPaypalEmailChange={setPaypalEmail} onWalletPay={handleWalletPay}/>
          </div>
        )}

        {/* Send button */}
        {!sent&&(
          <button onClick={()=>{if(payMethod==='qr'){handleSend().then(()=>setShowQR(true));}else handleSend();}}
            disabled={sending}
            className={`w-full py-4 rounded-2xl font-black text-sm text-white flex items-center justify-center gap-2 active:scale-95 transition-all ${fClass}`}
            style={{background:sending?'#9CA3AF':'#6366F1',boxShadow:sending?'none':'0 6px 20px rgba(99,102,241,0.4)',cursor:sending?'not-allowed':'pointer'}}>
            {sending?(
              <><span className="w-4 h-4 rounded-full border-2 border-white/40 border-t-white animate-spin"/>{lang==='ar'?'جارٍ الإرسال…':lang==='en'?'Sending…':'Envoi en cours…'}</>
            ):(
              <><span>🛵</span>{lang==='ar'?'تأكيد الطلب':lang==='en'?'Place order':'Commander'}</>
            )}
          </button>
        )}
        {showQR&&<QRPayModal lang={lang} onClose={()=>setShowQR(false)} onConfirm={()=>setShowQR(false)}/>}
      </div>
    </div>
  );
}

// ─── HORAIRES D'OUVERTURE ──────────────────────────────────────────────────
// Horaires indicatifs par service, utilisés uniquement pour l'affichage d'un
// badge "Ouvert/Fermé" sur la page d'accueil. Mode "distributeur" : le client
// peut commander à tout moment même si le service est marqué fermé — rien
// n'est bloqué, la commande est simplement traitée dès la réouverture.
const SERVICE_HOURS: Record<string,{open:number;close:number}> = {
  delivery:    {open:8, close:24},
  fleurs:      {open:8, close:24},
  supermarche: {open:8, close:24},
  boulangerie: {open:6, close:24},
  souk:        {open:9, close:24},
};
function isServiceOpen(key:string):{open:boolean;opensAt:number;closesAt:number}{
  const h=SERVICE_HOURS[key];
  if(!h) return {open:true,opensAt:0,closesAt:24};
  const now=new Date().getHours();
  const open = h.open<h.close ? (now>=h.open&&now<h.close) : (now>=h.open||now<h.close);
  return {open,opensAt:h.open,closesAt:h.close};
}
function HoursBadge({k}:{k:string}) {
  const st=isServiceOpen(k);
  return (
    <span style={{
      display:'inline-flex',alignItems:'center',gap:3,
      background:st.open?'rgba(16,185,129,0.25)':'rgba(239,68,68,0.25)',
      border:`1px solid ${st.open?'rgba(52,211,153,0.5)':'rgba(248,113,113,0.5)'}`,
      borderRadius:20,padding:'1px 6px',fontSize:7,fontWeight:900,color:'#fff',flexShrink:0,
    }}>
      <span style={{width:4,height:4,borderRadius:'50%',background:st.open?'#4ADE80':'#F87171',display:'inline-block'}}/>
      {st.open?'OUVERT':`FERMÉ · ${String(st.opensAt).padStart(2,'0')}H`}
    </span>
  );
}

// Vraies photos (Wikimedia Commons, licence libre) utilisées en arrière-plan des
// cartes services — remplace les logos/emoji pour un rendu plus pro. Chaque usage
// a un fallback silencieux (emoji/dégradé d'origine) si l'image ne charge pas.
// URLs directes upload.wikimedia.org (au lieu de Special:FilePath qui fait une
// redirection HTTP vers un AUTRE domaine -> connexion TLS supplementaire à
// chaque chargement = photos qui mettent du temps à apparaitre sur les cartes).
const CARD_PHOTOS: Record<string,string> = {
  delivery:    '/cover-eats.png',
  taxi:        '/cover-taxi.jpeg',
  fleurs:      '/cover-fleurs.png',
  tabac:       '/cover-tabac.png',
  pharmacie:   '/cover-pharmacie.png',
  supermarche: '/cover-supermarche.png',
  boulangerie: '/cover-boulangerie.png',
  souk:        '/cover-souk.png',
};
function MiniPhotoBadge({k,emoji,size=38}:{k:string;emoji:string;size?:number}) {
  const [ok,setOk]=useState(true);
  const src=CARD_PHOTOS[k];
  return (
    <div style={{width:size,height:size,borderRadius:9,overflow:'hidden',flexShrink:0,background:'rgba(255,255,255,0.1)',display:'flex',alignItems:'center',justifyContent:'center'}}>
      {ok
        ? <img src={src} alt="" loading="lazy" onError={()=>setOk(false)} style={{width:'100%',height:'100%',objectFit:'cover'}}/>
        : <span style={{fontSize:size*0.6,lineHeight:1,filter:'drop-shadow(0 4px 12px rgba(0,0,0,0.4))'}}>{emoji}</span>}
    </div>
  );
}

// ─── SERVICE SELECT PAGE ──────────────────────────────────────────────────────

function ServiceSelectPage({onSelect,onBack,lang,cycleLang,profile,saveProfile}:{onSelect:(s:'delivery'|'taxi'|'tabac'|'fleurs'|'pharmacie'|'boulangerie'|'souk'|'supermarche')=>void;onBack:()=>void;lang:Lang;cycleLang:()=>void;profile:UserProfile;saveProfile:(p:UserProfile)=>void}) {
  const [pressed,setPressed]=useState<'delivery'|'taxi'|'tabac'|'fleurs'|'pharmacie'|'boulangerie'|'souk'|'supermarche'|null>(null);
  const [showProfile,setShowProfile]=useState(false);
  // Coupe-circuit temporaire de la vidéo pub (consommait trop de bande passante Railway)
  const AD_VIDEO_ENABLED = false;
  const pubVideoRef=useRef<HTMLVideoElement>(null);
  const [pubMuted,setPubMuted]=useState(true);
  const [,navigate]=useLocation();
  const { user } = useUser(); const { isSignedIn } = useAuth();
  const getAuthHeaders=useAuthHeaders();
  const t=T[lang]; const fClass=fontClass(lang); const isAR=lang==='ar';
  const LANG_LABELS:Record<Lang,string>={fr:'FR',en:'EN',ar:'AR',amz:'ⴰⵎⵣ'};
  const choose=(s:'delivery'|'taxi'|'tabac'|'fleurs'|'pharmacie'|'boulangerie'|'souk'|'supermarche')=>{setPressed(s);setTimeout(()=>onSelect(s),320);};
  // Avatar: custom upload > Clerk photo > initials
  const avatarSrc=profile.avatar||user?.imageUrl||null;
  // Le profil local (onboarding) peut être vide même si le compte est bien connecté —
  // on utilise les vraies infos du compte (bridge-auth) en repli pour ne jamais afficher
  // un ID/avatar cassé ("BR-???????") tant que la personne est réellement connectée.
  const effectiveName=profile.name||user?.name||'';
  const effectivePhone=profile.phone||user?.phone||'';
  const initials=(effectiveName||'?').split(' ').map(w=>w[0]).join('').toUpperCase().slice(0,2);
  // Diamonds — même source que SharkDiamondWidget (/api/game/diamonds + cache locale par user.id)
  // pour que le compte de diamants soit toujours identique partout dans l'app (avant : cette page
  // interrogeait une API externe par numéro de téléphone, désynchronisée du reste de l'app).
  const diamondsCacheKey=`bridge_diamonds_cache_${user?.id||'anon'}`;
  const [diamonds, setDiamonds] = useState<number>(()=>{
    try{return parseInt(localStorage.getItem(`bridge_diamonds_cache_${user?.id||'anon'}`)||'0',10)||0;}catch{return 0;}
  });
  useEffect(()=>{
    if(!user?.id) return;
    getAuthHeaders().then(h=>fetch('/api/game/diamonds',{credentials:'include',headers:h})
      .then(r=>r.ok?r.json():null)
      .then(d=>{
        if(d&&typeof d.diamonds==='number'){
          setDiamonds(d.diamonds);
          try{localStorage.setItem(diamondsCacheKey,String(d.diamonds));}catch{}
        }
      })
      .catch(()=>{}));
  },[user?.id,getAuthHeaders,diamondsCacheKey]);
  useEffect(()=>{
    const onStorage=(e:StorageEvent)=>{
      if(e.key===diamondsCacheKey&&e.newValue){
        const n=parseInt(e.newValue,10);
        if(!isNaN(n)&&n>=0) setDiamonds(n);
      }
    };
    window.addEventListener('storage',onStorage);
    return()=>window.removeEventListener('storage',onStorage);
  },[diamondsCacheKey]);
  // Compte rapide des commandes récentes (hors taxi/moto) pour le badge du
  // bouton "Suivre mes commandes" — pas d'appel réseau ici, juste le cache local.
  const [recentOrdersCount,setRecentOrdersCount]=useState(0);
  useEffect(()=>{
    try{
      const raw=localStorage.getItem('bridge_history');
      const arr:{type:string;date:string;owner?:string}[]=raw?JSON.parse(raw):[];
      const THREE_H=3*60*60*1000;
      const owner=user?.id||'guest';
      const recent=arr.filter(e=>e.type!=='taxi'&&e.type!=='moto'&&(e.owner||'guest')===owner&&(Date.now()-new Date(e.date).getTime())<THREE_H);
      setRecentOrdersCount(recent.length);
    }catch{}
  },[user?.id]);
 

  return(
    <div className={`fixed inset-0 flex flex-col z-40 ${isAR?'rtl':'ltr'}`}
      style={{background:'var(--c-bg)',overflowY:'auto'}}>
      <style>{`
        @keyframes svcFloat{0%,100%{transform:translateY(0) rotate(0deg);}50%{transform:translateY(-9px) rotate(4deg);}}
        @keyframes svcFadeUp{0%{opacity:0;transform:translateY(22px) scale(0.96);}100%{opacity:1;transform:translateY(0) scale(1);}}
        @keyframes svcShine{0%{left:-100%;}100%{left:200%;}}
        @keyframes svcPulseRed{0%,100%{box-shadow:0 8px 32px rgba(185,28,28,0.35);}50%{box-shadow:0 8px 48px rgba(185,28,28,0.7);}}
      `}</style>

      {/* SAFI badge trilingue — TOP CENTER (remplace le bouton HUB) */}
      <div className="absolute top-4 left-1/2 z-50" style={{transform:'translateX(-50%)',display:'flex',flexDirection:'column',alignItems:'center',gap:4,pointerEvents:'none'}}>
        <div style={{
          display:'inline-flex',alignItems:'center',gap:7,
          background:'linear-gradient(135deg,rgba(6,95,70,0.1),rgba(180,83,9,0.07))',
          border:'1px solid rgba(217,197,160,0.7)',
          borderRadius:22,padding:'5px 18px',
          backdropFilter:'blur(12px)',
          boxShadow:'0 2px 14px rgba(6,95,70,0.12)',
          whiteSpace:'nowrap',
        }}>
          <span style={{fontSize:11,fontWeight:900,letterSpacing:'0.14em',color:'#065F46'}}>SAFI</span>
          <span style={{color:'#D9C5A0',fontSize:11}}>·</span>
          <span style={{fontSize:11,fontWeight:700,color:'#B45309',fontFamily:'serif'}}>أسفي</span>
          <span style={{color:'#D9C5A0',fontSize:11}}>·</span>
          <span style={{fontSize:11,fontWeight:700,color:'#065F46'}} className="font-tifinagh">ⵙⴰⴼⵉ</span>
        </div>
        <div style={{width:7,height:7,borderRadius:'50%',background:'linear-gradient(135deg,#34D399,#B45309)',boxShadow:'0 0 8px rgba(5,150,105,0.5)'}}/>
      </div>

      {/* LEFT — HUB + Se connecter / Profil côte à côte */}
      <div className={`absolute top-5 z-50 flex flex-row items-center gap-2 ${isAR?'right-5':'left-5'}`}>
        {/* Cercle HUB — retour page 1 */}
        <button onClick={onBack}
          className="rounded-full flex items-center justify-center transition-all active:scale-90 hover:scale-110"
          title="Retour Hub"
          style={{width:38,height:38,background:'var(--c-card)',border:'2.5px solid #D9C5A0',color:'#065F46',boxShadow:'0 4px 20px rgba(6,95,70,0.15)',cursor:'pointer',fontSize:16,fontWeight:900}}>
          ⌂
        </button>
        {/* Cercle Se connecter ou Profil */}
        {isSignedIn?(
          <button onClick={()=>setShowProfile(true)}
            className="rounded-full transition-all active:scale-90 hover:scale-110"
            style={{width:38,height:38,borderRadius:'50%',overflow:'hidden',border:'2.5px solid #D9C5A0',background:'#F0EBE1',boxShadow:'0 4px 14px rgba(6,95,70,0.15)',cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center',padding:0}}>
            {avatarSrc
              ?<img src={avatarSrc} alt="Profil" style={{width:'100%',height:'100%',objectFit:'cover'}}/>
              :<span style={{fontSize:13,fontWeight:900,color:'#065F46',lineHeight:1}}>{initials}</span>
            }
          </button>
        ):(
          <button onClick={()=>window.location.href='/sign-in'}
            className="rounded-full flex items-center justify-center transition-all active:scale-90 hover:scale-110"
            title="Se connecter"
            style={{width:38,height:38,background:'linear-gradient(135deg,#065F46,#059669)',border:'2.5px solid rgba(52,211,153,0.5)',color:'#fff',boxShadow:'0 4px 16px rgba(6,95,70,0.35)',cursor:'pointer',fontSize:18}}>
            👤
          </button>
        )}
      </div>  
      
      {/* Language + Dark toggle — RIGHT */}
      <div className={`absolute top-5 z-50 flex items-center gap-2 ${isAR?'left-5':'right-5'}`}>
        {/* Bouton Aide retire d'ici (demande zabi 2026-07-10) -> deplace dans FloatingHelpWA, a cote du WhatsApp, affiche partout */}
        <DarkToggle size={38}/>
        <button onClick={cycleLang}
          className={`rounded-full flex items-center justify-center font-black text-sm transition-all active:scale-90 hover:scale-110 px-3 ${lang==='amz'?'font-tifinagh':''}`}
          style={{background:'var(--c-card)',border:'2.5px solid #D9C5A0',color:'#065F46',boxShadow:'0 4px 20px rgba(6,95,70,0.15)',height:'38px',fontSize:'13px'}}>
          {LANG_LABELS[lang]}
        </button>
      </div>

      <div className="relative flex flex-col items-center w-full max-w-2xl mx-auto pt-20 pb-8 px-4">
        {/* Sous-titre dans glass pill */}
        <div style={{
          background:'linear-gradient(135deg,rgba(6,95,70,0.08),rgba(217,197,160,0.12))',
          border:'1px solid rgba(217,197,160,0.4)',
          borderRadius:12,padding:'5px 16px',
          backdropFilter:'blur(8px)',marginBottom:24,
        }}>
          <p className={`text-[10px] font-black tracking-[0.18em] uppercase ${fClass}`} style={{color:'#6B7280',margin:0}}>{t.chooseService}</p>
        </div>

        {/* 2×2 service grid — Glassmorphism iOS 18 */}
        {(()=>{
          const topItems=[
            {key:'delivery' as const, label:'Bridge Eats',  sub:t.deliverySub, emoji:'🍕🍔',
             pending:false, active:true,
             grad:'linear-gradient(145deg,#064E3B 0%,#065F46 45%,#059669 100%)',
             glow:'rgba(5,150,105,0.55)', border:'rgba(52,211,153,0.45)', pill:'rgba(5,150,105,0.8)', bottom:'#059669'},
            {key:'taxi'     as const, label:'Bridge Taxi',  sub:t.taxiSub,     emoji:'🚖🛵',
             pending:true,
             grad:'linear-gradient(145deg,#78350F 0%,#B45309 55%,#F59E0B 100%)',
             glow:'rgba(245,158,11,0.45)', border:'rgba(251,191,36,0.45)', pill:'rgba(180,83,9,0.85)', bottom:'#B45309'},
          ];
          const botItems=[
            {key:'fleurs'   as const, label:'Bridge Fleurs',sub:t.fleursSub,   emoji:'🌹',
             pending:false, active:true,
             grad:'linear-gradient(145deg,#831843 0%,#DB2777 55%,#F472B6 100%)',
             glow:'rgba(219,39,119,0.5)', border:'rgba(244,114,182,0.45)', pill:'rgba(219,39,119,0.8)', bottom:'#DB2777'},
            {key:'tabac'    as const, label:'Bridge Tabac', sub:t.tabacSub,    emoji:'🚬',
             pending:true,
             grad:'linear-gradient(145deg,#1C0A00 0%,#7D4F2E 55%,#A0623A 100%)',
             glow:'rgba(125,79,46,0.5)', border:'rgba(160,98,58,0.4)', pill:'rgba(125,79,46,0.85)', bottom:'#7D4F2E'},
          ];
          const cardIdx:{[k:string]:number}={delivery:0,taxi:1,fleurs:3,tabac:4};
          const renderCard=(item:{key:'delivery'|'taxi'|'fleurs'|'tabac'|'pharmacie'|'supermarche';label:string;sub:string;emoji:string;pending?:boolean;grad:string;glow:string;border:string;pill?:string;bottom?:string;photo?:string})=>{
            const isPressed=pressed===item.key;
            const idx=cardIdx[item.key]??0;
            return(
              <button key={item.key} onClick={()=>choose(item.key)}
                style={{
                  background:'none',border:'none',cursor:'pointer',padding:0,
                  transform:isPressed?'scale(0.94)':'scale(1)',
                  transition:'transform 0.2s cubic-bezier(.34,1.56,.64,1)',
                  opacity:item.pending?0.82:1,
                  animation:`svcFadeUp 0.45s ease-out ${idx*0.08}s both`,
                }}>
                <div style={{
                  background: item.grad,
                  borderRadius:18,
                  border:`1.5px solid ${isPressed?'rgba(255,255,255,0.55)':item.border}`,
                  boxShadow: isPressed
                    ? `0 0 0 3px ${item.glow},0 16px 40px ${item.glow},inset 0 1px 0 rgba(255,255,255,0.25)`
                    : `0 8px 32px ${item.glow},inset 0 1px 0 rgba(255,255,255,0.2)`,
                  padding:0,
                  display:'flex',flexDirection:'column',alignItems:'stretch',justifyContent:'flex-end',
                  position:'relative',overflow:'hidden',
                  transition:'box-shadow 0.25s,border-color 0.25s',
                  minHeight:172,
                }}>
                  <img src={CARD_PHOTOS[item.key]} alt="" loading="lazy"
                    onError={(e)=>{(e.currentTarget as HTMLImageElement).style.display='none';}}
                    style={{position:'absolute',top:0,left:0,right:0,height:'100%',width:'100%',objectFit:'cover',objectPosition:'center',opacity:0.95}}/>
                  <div style={{position:'absolute',top:0,left:0,right:0,height:item.key==='taxi'?'82%':'92%',background:'linear-gradient(180deg,rgba(0,0,0,0.05) 0%,rgba(0,0,0,0) 35%,rgba(0,0,0,0.82) 100%)',pointerEvents:'none'}}/>
                  <div style={{position:'absolute',top:0,left:0,right:0,height:'90%',background:'linear-gradient(180deg,rgba(255,255,255,0.18) 0%,rgba(255,255,255,0) 100%)',borderRadius:'10px 10px 60% 60%',pointerEvents:'none'}}/>
                  <div style={{position:'absolute',top:0,bottom:0,width:'40%',background:'linear-gradient(90deg,transparent,rgba(255,255,255,0.07),transparent)',animation:'svcShine 3.5s ease-in-out infinite',pointerEvents:'none'}}/>
                  {/* Bulle moderne haut-droite : OUVERT / EN ATTENTE */}
                  {(()=>{
                    const st=isServiceOpen(item.key);
                    const isPending=item.pending;
                    const bg=isPending?'rgba(220,38,38,0.82)':st.open?'rgba(5,150,105,0.82)':'rgba(220,38,38,0.82)';
                    const dot=isPending?'#FCA5A5':st.open?'#6EE7B7':'#FCA5A5';
                    const label=isPending?'EN ATTENTE':st.open?'OUVERT':'FERMÉ';
                    return(
                      <div style={{position:'absolute',top:6,right:isAR?'auto':6,left:isAR?6:'auto',zIndex:10,
                        background:bg,backdropFilter:'blur(12px)',WebkitBackdropFilter:'blur(12px)',
                        borderRadius:20,padding:'2px 6px',display:'flex',alignItems:'center',gap:3,
                        boxShadow:'0 1px 6px rgba(0,0,0,0.25)',border:'1px solid rgba(255,255,255,0.18)'}}>
                        <span style={{width:4,height:4,borderRadius:'50%',background:dot,display:'inline-block',flexShrink:0,
                          boxShadow:`0 0 4px ${dot}`,animation:'pulse2 1.4s ease-in-out infinite'}}/>
                        <span style={{color:'#fff',fontSize:6,fontWeight:800,letterSpacing:'0.06em',whiteSpace:'nowrap'}}>{label}</span>
                      </div>
                    );
                  })()}
                  <p style={{color:'#fff',fontSize:14,fontWeight:900,letterSpacing:'0.03em',margin:'0 0 5px',textShadow:'0 2px 8px rgba(0,0,0,0.9)',textAlign:'center',position:'relative',zIndex:2,paddingLeft:8,paddingRight:8}}>{item.label}</p>
                  <div style={{background:item.bottom??'rgba(0,0,0,0.7)',padding:'3px 14px',display:'flex',alignItems:'center',justifyContent:'center',position:'relative',zIndex:2,width:'100%',boxSizing:'border-box'}}>
                    <p style={{color:'#fff',fontSize:9,fontWeight:700,margin:0,textAlign:'center',letterSpacing:'0.03em'}}>{item.sub}</p>
                  </div>
                </div>
              </button>
            );
          };
          return(
            <div style={{display:'flex',flexDirection:'column',gap:'16px',width:'100%',maxWidth:'100%',padding:'0 16px'}}>
              {/* Row 1: Eats + Taxi */}
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'16px'}}>
                {topItems.map(renderCard)}
              </div>
              {/* Row 2: Pharmacie + Supermarché */}
              {(()=>{
                const midItems=[
                  {key:'pharmacie' as const, label:'Bridge Pharmacie', sub:t.pharmaeSub,    emoji:'💊', pending:true,  grad:'linear-gradient(145deg,#0C0E2B 0%,#1E1B4B 35%,#312E81 65%,#1D4ED8 100%)', glow:'rgba(99,102,241,0.55)',  border:'rgba(99,102,241,0.45)',  bottom:'#4338CA'},
                  {key:'supermarche' as const, label:'Bridge Supermarché', sub:t.supermarcheSub, emoji:'🛒', pending:false, grad:'linear-gradient(145deg,#450A0A 0%,#7F1D1D 55%,#EF4444 100%)',           glow:'rgba(239,68,68,0.5)',    border:'rgba(239,68,68,0.45)',    bottom:'#DC2626'},
                ];
                return(
                  <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'16px'}}>
                    {midItems.map(renderCard)}
                  </div>
                );
              })()}
              {/* Row 3: Fleurs + Tabac */}
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'16px'}}>
                {botItems.map(renderCard)}
              </div>
              {/* Row 5: Boulangerie + Souk — nouvelles cartes (actives) */}
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'16px'}}>
                <button onClick={()=>choose('boulangerie')} style={{background:'none',border:'none',cursor:'pointer',padding:0,transform:pressed==='boulangerie'?'scale(0.94)':'scale(1)',transition:'transform 0.2s cubic-bezier(.34,1.56,.64,1)',animation:'svcFadeUp 0.45s ease-out 0.32s both'}}>
                  <div style={{
                    background:'linear-gradient(145deg,#422006 0%,#A16207 55%,#FACC15 100%)',
                    borderRadius:18,border:`1.5px solid ${pressed==='boulangerie'?'rgba(255,255,255,0.55)':'rgba(250,204,21,0.45)'}`,
                    boxShadow:pressed==='boulangerie'?'0 0 0 3px rgba(250,204,21,0.5),0 16px 40px rgba(250,204,21,0.4),inset 0 1px 0 rgba(255,255,255,0.25)':'0 8px 32px rgba(161,98,7,0.45),inset 0 1px 0 rgba(255,255,255,0.2)',
                    padding:0,display:'flex',flexDirection:'column',alignItems:'stretch',justifyContent:'flex-end',
                    position:'relative',overflow:'hidden',minHeight:172,
                  }}>
                    <img src={CARD_PHOTOS.boulangerie} alt="" loading="lazy"
                      onError={(e)=>{(e.currentTarget as HTMLImageElement).style.display='none';}}
                      style={{position:'absolute',top:0,left:0,right:0,height:'100%',width:'100%',objectFit:'cover',objectPosition:'center',opacity:0.95}}/>
                    <div style={{position:'absolute',top:0,left:0,right:0,height:'100%',background:'linear-gradient(180deg,rgba(0,0,0,0.05) 0%,rgba(0,0,0,0) 35%,rgba(0,0,0,0.82) 100%)',pointerEvents:'none'}}/>
                    {(()=>{const st=isServiceOpen('boulangerie');return(<div style={{position:'absolute',top:6,right:6,zIndex:10,background:st.open?'rgba(5,150,105,0.82)':'rgba(220,38,38,0.82)',backdropFilter:'blur(12px)',borderRadius:20,padding:'2px 6px',display:'flex',alignItems:'center',gap:3,boxShadow:'0 1px 6px rgba(0,0,0,0.25)',border:'1px solid rgba(255,255,255,0.18)'}}><span style={{width:4,height:4,borderRadius:'50%',background:st.open?'#6EE7B7':'#FCA5A5',display:'inline-block',flexShrink:0,boxShadow:`0 0 4px ${st.open?'#6EE7B7':'#FCA5A5'}`,animation:'pulse2 1.4s ease-in-out infinite'}}/><span style={{color:'#fff',fontSize:6,fontWeight:800,letterSpacing:'0.06em'}}>{st.open?'OUVERT':'FERMÉ'}</span></div>);})()}
                    <p style={{color:'#fff',fontSize:14,fontWeight:900,letterSpacing:'0.03em',margin:'0 0 5px',textShadow:'0 2px 8px rgba(0,0,0,0.9)',textAlign:'center',position:'relative',zIndex:2,paddingLeft:8,paddingRight:8}}>Bridge Boulangerie</p>
                    <div style={{background:'#A16207',padding:'3px 14px',display:'flex',alignItems:'center',justifyContent:'center',position:'relative',zIndex:2,width:'100%',boxSizing:'border-box'}}>
                      <p style={{color:'#fff',fontSize:9,fontWeight:700,margin:0,textAlign:'center',letterSpacing:'0.03em'}}>{t.boulangerieSub}</p>
                    </div>
                  </div>
                </button>
                <button onClick={()=>choose('souk')} style={{background:'none',border:'none',cursor:'pointer',padding:0,transform:pressed==='souk'?'scale(0.94)':'scale(1)',transition:'transform 0.2s cubic-bezier(.34,1.56,.64,1)',animation:'svcFadeUp 0.45s ease-out 0.4s both'}}>
                  <div style={{
                    background:'linear-gradient(145deg,#3B0764 0%,#7E22CE 55%,#C084FC 100%)',
                    borderRadius:18,border:`1.5px solid ${pressed==='souk'?'rgba(255,255,255,0.55)':'rgba(192,132,252,0.45)'}`,
                    boxShadow:pressed==='souk'?'0 0 0 3px rgba(192,132,252,0.5),0 16px 40px rgba(192,132,252,0.4),inset 0 1px 0 rgba(255,255,255,0.25)':'0 8px 32px rgba(126,34,206,0.45),inset 0 1px 0 rgba(255,255,255,0.2)',
                    padding:0,display:'flex',flexDirection:'column',alignItems:'stretch',justifyContent:'flex-end',
                    position:'relative',overflow:'hidden',minHeight:172,
                  }}>
                    <img src={CARD_PHOTOS.souk} alt="" loading="lazy"
                      onError={(e)=>{(e.currentTarget as HTMLImageElement).style.display='none';}}
                      style={{position:'absolute',top:0,left:0,right:0,height:'100%',width:'100%',objectFit:'cover',objectPosition:'center',opacity:0.95}}/>
                    <div style={{position:'absolute',top:0,left:0,right:0,height:'100%',background:'linear-gradient(180deg,rgba(0,0,0,0.05) 0%,rgba(0,0,0,0) 35%,rgba(0,0,0,0.82) 100%)',pointerEvents:'none'}}/>
                    {(()=>{const st=isServiceOpen('souk');return(<div style={{position:'absolute',top:6,right:6,zIndex:10,background:st.open?'rgba(5,150,105,0.82)':'rgba(220,38,38,0.82)',backdropFilter:'blur(12px)',borderRadius:20,padding:'2px 6px',display:'flex',alignItems:'center',gap:3,boxShadow:'0 1px 6px rgba(0,0,0,0.25)',border:'1px solid rgba(255,255,255,0.18)'}}><span style={{width:4,height:4,borderRadius:'50%',background:st.open?'#6EE7B7':'#FCA5A5',display:'inline-block',flexShrink:0,boxShadow:`0 0 4px ${st.open?'#6EE7B7':'#FCA5A5'}`,animation:'pulse2 1.4s ease-in-out infinite'}}/><span style={{color:'#fff',fontSize:6,fontWeight:800,letterSpacing:'0.06em'}}>{st.open?'OUVERT':'FERMÉ'}</span></div>);})()}
                    <p style={{color:'#fff',fontSize:14,fontWeight:900,letterSpacing:'0.03em',margin:'0 0 5px',textShadow:'0 2px 8px rgba(0,0,0,0.9)',textAlign:'center',position:'relative',zIndex:2,paddingLeft:8,paddingRight:8}}>Bridge Souk</p>
                    <div style={{background:'#7E22CE',padding:'3px 14px',display:'flex',alignItems:'center',justifyContent:'center',position:'relative',zIndex:2,width:'100%',boxSizing:'border-box'}}>
                      <p style={{color:'#fff',fontSize:9,fontWeight:700,margin:0,textAlign:'center',letterSpacing:'0.03em'}}>{t.soukSub}</p>
                    </div>
                  </div>
                </button>
              </div>
              {/* SUIVRE MES COMMANDES — entre Boulangerie/Souk et le jeu */}
              <button onClick={()=>navigate('/mes-commandes')}
                style={{
                  display:'flex',alignItems:'center',justifyContent:'space-between',gap:10,
                  width:'100%',padding:'14px 18px',borderRadius:18,cursor:'pointer',
                  background:'linear-gradient(145deg,#0a0a0a 0%,#161616 55%,#0a0a0a 100%)',
                  border:'1.5px solid rgba(217,197,160,0.4)',
                  boxShadow:'0 8px 28px rgba(0,0,0,0.45),inset 0 1px 0 rgba(255,255,255,0.08)',
                }}>
                <div style={{display:'flex',alignItems:'center',gap:10,minWidth:0}}>
                  <div style={{width:38,height:38,borderRadius:12,background:'rgba(16,185,129,0.15)',border:'1px solid rgba(16,185,129,0.35)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:18,flexShrink:0}}>📦</div>
                  <div style={{textAlign:'left',minWidth:0}}>
                    <p style={{color:'#fff',fontSize:14,fontWeight:900,margin:0}} className={fClass}>
                      {lang==='ar'?'تتبع طلباتي':lang==='en'?'Track my orders':'Suivre mes commandes'}
                    </p>
                    <p style={{color:'rgba(255,255,255,0.55)',fontSize:9,fontWeight:600,margin:'2px 0 0'}} className={fClass}>
                      {lang==='ar'?'GPS مباشر · وقت الوصول':lang==='en'?'Live GPS · arrival time':'GPS en direct · heure d\'arrivée'}
                    </p>
                  </div>
                </div>
                {recentOrdersCount>0 ? (
                  <span style={{background:'#10B981',color:'#04140D',fontSize:11,fontWeight:900,borderRadius:20,padding:'4px 10px',display:'flex',alignItems:'center',gap:4,flexShrink:0}}>
                    <span style={{width:6,height:6,borderRadius:'50%',background:'#04140D',display:'inline-block',animation:'pulse2 1.4s ease-in-out infinite'}}/>
                    {recentOrdersCount}
                  </span>
                ) : (
                  <span style={{color:'rgba(255,255,255,0.35)',fontSize:14,flexShrink:0}}>{isAR?'←':'→'}</span>
                )}
              </button>
            </div>
          );
        })()}

        {/* ── GAME BANNER — entre grille et pub ─────────────────────────────── */}
        <button onClick={()=>navigate('/game')}
          className="w-full mt-12 transition-all active:scale-95"
          style={{background:'linear-gradient(135deg,#071A10,#0D3020)',border:'1.5px solid rgba(74,222,128,0.35)',borderRadius:20,padding:'14px 18px',boxShadow:'0 6px 28px rgba(6,95,70,0.45)',cursor:'pointer',display:'flex',alignItems:'center',gap:14,textAlign:'left'}}>
          {/* Shark avatar */}
          <div style={{width:52,height:52,borderRadius:'50%',overflow:'hidden',border:'2px solid #D9C5A0',flexShrink:0,boxShadow:'0 0 16px rgba(74,222,128,0.4)'}}>
            <img src="/bridge-shark.png" alt="Bridge Game" style={{width:'100%',height:'100%',objectFit:'cover',objectPosition:'center top'}}/>
          </div>
          {/* Text */}
          <div style={{flex:1,minWidth:0}}>
            <div style={{display:'flex',alignItems:'center',gap:6,marginBottom:3}}>
              <span style={{color:'#D9C5A0',fontSize:9,fontWeight:900,letterSpacing:'0.22em'}}>BRIDGE</span>
              <span style={{background:'rgba(74,222,128,0.2)',border:'1px solid rgba(74,222,128,0.6)',borderRadius:5,padding:'1px 6px',color:'#4ADE80',fontSize:8,fontWeight:900,letterSpacing:'0.14em'}}>GAME</span>
            </div>
            <p style={{color:'#FDE047',fontSize:12,fontWeight:800,margin:'0 0 2px',lineHeight:1.3}}>💎 Gagnez des diamants</p>
            <p style={{color:'rgba(255,255,255,0.45)',fontSize:10,margin:0}}>{t.gameOrderPoints}</p>
          </div>
          {/* Arrow */}
          <span style={{color:'#4ADE80',fontSize:18,flexShrink:0,fontWeight:900}}>›</span>
        </button>

        {/* ── AD SLOT — place de publicité ───────────────────────────────────── */}
        {/* Vidéo désactivée temporairement (2026-07-10) : la lecture auto + boucle
            consommait trop de bande passante Railway. Repasser AD_VIDEO_ENABLED
            à true pour la réactiver. */}
        {AD_VIDEO_ENABLED && (
        <div id="ad-slot" className="w-full mt-5" style={{position:'relative'}}>
          <a href="https://grado.safi-bridge.ma" className="block rounded-2xl overflow-hidden" style={{border:'1.5px dashed #D9C5A0',background:'rgba(253,252,249,0.7)'}}>
            {/* PUB_CONTENT_START */}
            <video ref={pubVideoRef} src="/pub-video.mp4" autoPlay loop muted playsInline
              style={{width:'100%',height:'160px',display:'block',objectFit:'cover'}}/>
            {/* PUB_CONTENT_END */}
          </a>
          {/* Bouton son — reste fixe même si la vidéo change, masque aussi le watermark IA */}
          <button
            onClick={(e)=>{e.preventDefault();e.stopPropagation();const v=pubVideoRef.current;if(v){v.muted=!v.muted;setPubMuted(v.muted);}}}
            style={{position:'absolute',top:8,right:8,width:30,height:30,borderRadius:'50%',background:'rgba(0,0,0,0.55)',backdropFilter:'blur(4px)',border:'1px solid rgba(255,255,255,0.35)',display:'flex',alignItems:'center',justifyContent:'center',cursor:'pointer',zIndex:2,padding:0}}>
            <span style={{fontSize:14,lineHeight:1}}>{pubMuted?'🔇':'🔊'}</span>
          </button>
        </div>
        )}

      </div>

      {showProfile&&<ProfileModal lang={lang} profile={profile} onSave={saveProfile} onClose={()=>setShowProfile(false)}/>}
    </div>
  );
}

