// ─── HISTORY PAGE ─────────────────────────────────────────────────────────────
type HistoryEntry = {
  ref: string;
  type: 'eats'|'tabac'|'pharmacie'|'fleurs'|'boulangerie'|'souk'|'supermarche'|'taxi'|'moto';
  date: string;
  total?: number;
  destination?: string;
  address?: string;
  name?: string;
  restaurantName?: string;
  owner?: string; // user?.id du compte qui a passé la commande, ou 'guest' si non connecté
};

export function HistoryPageRoute() {
  const [,navigate]=useLocation();
  const {dark}=useDark();
  const { isSignedIn, user } = useUser();
  const { getToken } = useAuth();
  const [lang]=useState<Lang>(()=>{try{const r=localStorage.getItem(NAV_KEY);return r?JSON.parse(r).lang??'fr':'fr';}catch{return 'fr';}});
  const t=T[lang];
  // Ne garde que les entrées de CE compte (ou les entrées 'guest' non connecté) —
  // corrige le bug où l'historique d'un appareil partagé mélangeait les commandes
  // de plusieurs clients différents.
  const currentOwner=user?.id||'guest';
  const [entries,setEntries]=useState<HistoryEntry[]>(()=>{
    try{const r=localStorage.getItem('bridge_history');const arr:HistoryEntry[]=r?JSON.parse(r):[];return arr.filter(e=>(e.owner||'guest')===currentOwner);}catch{return [];}
  });

  // Compte connecté → historique propre à ce compte, servi depuis le serveur
  // (voir MyOrdersPageRoute pour le détail du bug corrigé). Persiste après
  // déconnexion : reconnecter le même compte réaffiche le même historique.
  useEffect(()=>{
    if(!isSignedIn) return;
    let cancelled=false;
    (async()=>{
      try{
        const token=await getToken();
        if(!token) return;
        const r=await fetch('/api/orders/mine',{headers:{Authorization:`Bearer ${token}`},cache:'no-store'});
        if(!r.ok) return;
        const data=await r.json();
        const serverEntries:HistoryEntry[]=(data.orders||[]).map((o:any)=>({
          ref:o.ref,type:o.service==='delivery'?'eats':o.service,date:o.createdAt,total:o.total,
          address:o.customerAddress,restaurantName:o.restaurantName??undefined,
        }));
        // Fusionne avec l'historique local au lieu de le remplacer : une commande
        // dont le numéro saisi à la caisse ne correspond pas exactement au numéro
        // du compte (ex. commande passée en invité, ou tapé différemment) ne doit
        // jamais disparaître alors qu'elle est bien dans le localStorage de l'appareil.
        if(!cancelled) setEntries(prev=>{
          const byRef=new Map<string,HistoryEntry>();
          serverEntries.forEach(e=>byRef.set(e.ref,e));
          prev.forEach(e=>{ if((e.owner||'guest')===currentOwner && !byRef.has(e.ref)) byRef.set(e.ref,e); });
          return Array.from(byRef.values()).sort((a,b)=>new Date(b.date).getTime()-new Date(a.date).getTime());
        });
      }catch{}
    })();
    return ()=>{cancelled=true;};
  },[isSignedIn]);
  const typeInfo:{[k:string]:{icon:string;label:string;color:string}}={
    eats:{icon:'🍔',label:'Bridge Eats',color:'#DC2626'},
    tabac:{icon:'🚬',label:'Bridge Tabac',color:'#6B7280'},
    pharmacie:{icon:'💊',label:'Bridge Pharmacie',color:'#7C3AED'},
    fleurs:{icon:'🌹',label:'Bridge Fleurs',color:'#DB2777'},
    boulangerie:{icon:'🥖',label:'Bridge Boulangerie',color:'#A16207'},
    souk:{icon:'🛍️',label:'Bridge Souk',color:'#7E22CE'},
    supermarche:{icon:'🛒',label:'Bridge Supermarché',color:'#EF4444'},
    taxi:{icon:'🚖',label:'Bridge Taxi',color:'#B45309'},
    moto:{icon:'🛵',label:'Bridge Moto',color:'#9A3412'},
  };
  const fmtDate=(iso:string)=>{
    try{const d=new Date(iso);return d.toLocaleDateString('fr-MA',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});}catch{return iso;}
  };
  return(
    <DarkModeCtx.Provider value={{dark,toggle:()=>{}}}>
    <div style={{background:dark?'#000':'#F9FAFB',minHeight:'100dvh',fontFamily:'system-ui,sans-serif'}}>
      <style>{`@keyframes hfadeIn{0%{opacity:0;transform:translateY(10px);}100%{opacity:1;transform:translateY(0);}}`}</style>
      {/* Header */}
      <div style={{background:dark?'#111':'#fff',padding:'52px 20px 14px',borderBottom:`1px solid ${dark?'#222':'#E5E7EB'}`,position:'sticky',top:0,zIndex:10,display:'flex',alignItems:'center',gap:12}}>
        <button onClick={()=>navigate('/')} style={{background:'none',border:'none',fontSize:20,cursor:'pointer',color:dark?'#fff':'#111',padding:'4px 8px',display:'flex',alignItems:'center',justifyContent:'center',width:36,height:36,borderRadius:'50%',flexShrink:0}}>←</button>
        <div style={{flex:1}}>
          <p style={{fontSize:9,fontWeight:800,letterSpacing:'0.2em',color:'#9CA3AF',margin:'0 0 1px'}}>BRIDGE SAFI</p>
          <h1 style={{fontSize:'1.1rem',fontWeight:900,color:dark?'#fff':'#111',margin:0}}>📋 {t.historyTitle}</h1>
        </div>
        <span style={{fontSize:11,color:'#9CA3AF',fontWeight:700}}>{entries.length} entrée{entries.length!==1?'s':''}</span>
      </div>
      {/* Content */}
      <div style={{padding:'16px',maxWidth:480,margin:'0 auto',boxSizing:'border-box' as const}}>
        {entries.length===0?(
          <div style={{textAlign:'center',padding:'80px 20px',animation:'hfadeIn 0.4s ease-out'}}>
            <div style={{fontSize:60,marginBottom:14}}>📭</div>
            <p style={{fontWeight:800,fontSize:17,color:dark?'#fff':'#374151',margin:'0 0 8px'}}>{t.historyEmpty}</p>
            <p style={{color:'#9CA3AF',fontSize:13,margin:'0 0 28px'}}>{t.historyEmptySub}</p>
            <button onClick={()=>navigate('/')} style={{padding:'12px 24px',borderRadius:14,border:'none',background:'linear-gradient(135deg,#065F46,#34D399)',color:'#fff',fontWeight:900,fontSize:14,cursor:'pointer'}}>
              {t.historyDiscover}
            </button>
          </div>
        ):entries.map((e,i)=>{
          const ti=typeInfo[e.type]||{icon:'📦',label:e.type,color:'#6B7280'};
          return(
            <div key={i} style={{background:dark?'#1C1C1E':'#fff',borderRadius:16,padding:'14px 16px',marginBottom:10,border:`1px solid ${dark?'#2C2C2E':'#E5E7EB'}`,boxShadow:'0 2px 8px rgba(0,0,0,0.05)',animation:`hfadeIn 0.3s ease-out ${i*0.04}s both`}}>
              <div style={{display:'flex',alignItems:'center',gap:12,marginBottom:8}}>
                <div style={{width:42,height:42,borderRadius:12,background:ti.color+'18',display:'flex',alignItems:'center',justifyContent:'center',fontSize:21,flexShrink:0,border:`1px solid ${ti.color}22`}}>{ti.icon}</div>
                <div style={{flex:1,minWidth:0}}>
                  <p style={{fontWeight:900,fontSize:14,color:dark?'#fff':'#111',margin:'0 0 2px'}}>{ti.label}</p>
                  <p style={{fontSize:10,color:'#9CA3AF',margin:0}}>{fmtDate(e.date)}</p>
                </div>
                <div style={{textAlign:'right' as const,flexShrink:0}}>
                  {(e.total??0)>0&&<p style={{fontWeight:900,fontSize:15,color:ti.color,margin:'0 0 2px'}}>{e.total} DH</p>}
                  <span style={{fontSize:10,fontWeight:700,color:'#059669',background:'rgba(5,150,105,0.1)',borderRadius:6,padding:'2px 7px'}}>{t.historyDone}</span>
                </div>
              </div>
              <div style={{fontSize:11,fontWeight:600,color:dark?'#D1D5DB':'#374151',background:dark?'#2C2C2E':'#F9FAFB',borderRadius:10,padding:'8px 12px',display:'flex',gap:6,flexWrap:'wrap' as const,alignItems:'center'}}>
                <span style={{color:ti.color,fontWeight:800}}>{e.ref}</span>
                {e.restaurantName&&<span style={{color:'#9CA3AF'}}>· {e.restaurantName}</span>}
                {e.name&&<span style={{color:'#9CA3AF'}}>· {e.name}</span>}
                {e.destination&&<><span style={{color:'#9CA3AF'}}>→</span><span>{e.destination}</span></>}
                {!e.destination&&e.address&&<span style={{color:'#9CA3AF'}}>· {e.address.split(',')[0]}</span>}
              </div>
            </div>
          );
        })}
        {entries.length>0&&(
          <button onClick={()=>{try{localStorage.removeItem('bridge_history');}catch{}setEntries([]);}}
            style={{width:'100%',padding:'13px',borderRadius:14,border:`1px solid ${dark?'#3C3C3E':'#FEE2E2'}`,background:'transparent',color:'#EF4444',fontWeight:700,fontSize:13,cursor:'pointer',marginTop:4}}>
            {t.historyClear}
          </button>
        )}
      </div>
    </div>
    <FloatingHelpWA/></DarkModeCtx.Provider>
  );
}


// ─── MES COMMANDES — suivi en direct de toutes les commandes (hors taxi/moto) ──
type ServiceThemeKey = 'eats'|'pharmacie'|'tabac'|'fleurs'|'boulangerie'|'souk'|'supermarche';
const ORDER_THEMES: Record<ServiceThemeKey, ServiceTrackTheme & {icon:string;label:string}> = {
  eats:        {icon:'🍔',label:'Bridge Eats',        emoji:'🍔',accent:'#059669',accentDark:'#065F46',accentLight:'#6EE7B7',cardBg:'var(--c-card)',cardBorder:'var(--c-border)',textColor:'var(--c-text)',mutedColor:'#9CA3AF'},
  pharmacie:   {icon:'💊',label:'Bridge Pharmacie',   emoji:'💊',accent:'#6366F1',accentDark:'#4338CA',accentLight:'#A5B4FC',cardBg:'rgba(99,102,241,0.15)',cardBorder:'rgba(99,102,241,0.5)',textColor:'#fff',mutedColor:'rgba(165,180,252,0.6)'},
  tabac:       {icon:'🚬',label:'Bridge Tabac',       emoji:'🚬',accent:'#B45309',accentDark:'#78350F',accentLight:'#FCD34D',cardBg:'var(--c-card)',cardBorder:'var(--c-border)',textColor:'var(--c-text)',mutedColor:'#9CA3AF'},
  fleurs:      {icon:'🌹',label:'Bridge Fleurs',      emoji:'💐',accent:'#A855F7',accentDark:'#7C3AED',accentLight:'#7C3AED',cardBg:'white',cardBorder:'#EDE9FE',textColor:'#4C1D95',mutedColor:'#9CA3AF'},
  boulangerie: {icon:'🥖',label:'Bridge Boulangerie', emoji:'🥖',accent:'#FACC15',accentDark:'#A16207',accentLight:'#FDE68A',cardBg:'rgba(161,98,7,0.2)',cardBorder:'rgba(250,204,21,0.5)',textColor:'#FEF3C7',mutedColor:'rgba(253,230,138,0.6)'},
  souk:        {icon:'🛍️',label:'Bridge Souk',        emoji:'🛍️',accent:'#C084FC',accentDark:'#7E22CE',accentLight:'#E9D5FF',cardBg:'rgba(126,34,206,0.2)',cardBorder:'rgba(192,132,252,0.5)',textColor:'#F3E8FF',mutedColor:'rgba(233,213,255,0.6)'},
  supermarche: {icon:'🛒',label:'Bridge Supermarché',   emoji:'🛒',accent:'#EF4444',accentDark:'#991B1B',accentLight:'#FCA5A5',cardBg:'rgba(239,68,68,0.2)',cardBorder:'rgba(252,165,165,0.5)',textColor:'#FEE2E2',mutedColor:'rgba(254,226,226,0.6)'},
};

type MyOrderEntry = HistoryEntry & { liveStatus?: string; etaLabel?: string };

// Projette une heure d'arrivée exacte (horloge, pas un compte à rebours) à partir
// de l'âge de la commande et de son statut — mêmes fenêtres que le reste de l'app
// (15 min préparation, 10 min trajet une fois "en route").
function projectArrival(orderDate: string, status: string): string | null {
  const DELIVERED = ['delivered','completed'];
  if (DELIVERED.includes(status)) return null;
  const ON_WAY = ['on_the_way','on_way'];
  const now = Date.now();
  let target: number;
  if (ON_WAY.includes(status)) {
    target = now + 10*60*1000;
  } else {
    const orderTime = new Date(orderDate).getTime();
    target = orderTime + 25*60*1000;
    if (target < now) target = now + 5*60*1000; // sécurité si déjà "en retard" sur l'estimation
  }
  const d = new Date(target);
  return d.toLocaleTimeString('fr-MA',{hour:'2-digit',minute:'2-digit'});
}

export function MyOrdersPageRoute() {
  const [,navigate]=useLocation();
  const {dark}=useDark();
  const { isSignedIn, user } = useUser();
  const { getToken } = useAuth();
  // Ne garde que les entrées de CE compte (ou 'guest' si non connecté) — voir
  // HistoryPageRoute pour le détail du bug corrigé (appareil partagé).
  const currentOwner=user?.id||'guest';
  const [lang,setLang]=useState<Lang>(()=>{try{const r=localStorage.getItem(NAV_KEY);return r?JSON.parse(r).lang??'fr':'fr';}catch{return 'fr';}});
  const cycleLang=()=>setLang(l=>{
    const next=LANG_CYCLE[(LANG_CYCLE.indexOf(l)+1)%LANG_CYCLE.length];
    try{const raw=localStorage.getItem(NAV_KEY);const parsed=raw?JSON.parse(raw):{};localStorage.setItem(NAV_KEY,JSON.stringify({...parsed,lang:next}));}catch{}
    return next;
  });
  const MYORD_LANG_LABELS:Record<Lang,string>={fr:'FR',en:'EN',ar:'AR',amz:'ⴰⵎⵣ'};
  const [entries,setEntries]=useState<MyOrderEntry[]>(()=>{
    try{
      const raw=localStorage.getItem('bridge_history');
      const arr:HistoryEntry[]=raw?JSON.parse(raw):[];
      return arr.filter(e=>e.type!=='taxi'&&e.type!=='moto'&&(e.owner||'guest')===currentOwner) as MyOrderEntry[];
    }catch{return [];}
  });
  const [openRef,setOpenRef]=useState<string|null>(null);

  // Compte connecté → l'historique vient du serveur (propre à CE compte, via
  // son numéro de téléphone), et non plus du localStorage de l'appareil.
  // Corrige le bug "tous les clients voient le même historique" (appareil
  // partagé) : chaque compte ne voit désormais que ses propres commandes,
  // et cet historique reste disponible même après déconnexion/reconnexion
  // (il est stocké côté serveur, pas perdu à la déconnexion).
  useEffect(()=>{
    if(!isSignedIn) return;
    let cancelled=false;
    (async()=>{
      try{
        const token=await getToken();
        if(!token) return;
        const r=await fetch('/api/orders/mine',{headers:{Authorization:`Bearer ${token}`},cache:'no-store'});
        if(!r.ok) return;
        const data=await r.json();
        const serverEntries:MyOrderEntry[]=(data.orders||[]).map((o:any)=>({
          ref:o.ref,type:o.service==='delivery'?'eats':o.service,date:o.createdAt,total:o.total,
          address:o.customerAddress,restaurantName:o.restaurantName??undefined,
        })).filter((e:MyOrderEntry)=>e.type!=='taxi'&&e.type!=='moto');
        // Fusionne avec l'historique local (voir HistoryPageRoute) : une commande
        // qui vient d'être passée ne doit pas disparaître de "Mes commandes" si le
        // numéro de la commande ne correspond pas exactement à celui du compte.
        if(!cancelled) setEntries(prev=>{
          const byRef=new Map<string,MyOrderEntry>();
          serverEntries.forEach(e=>byRef.set(e.ref,e));
          prev.forEach(e=>{ if((e.owner||'guest')!==currentOwner) return; if(!byRef.has(e.ref)) byRef.set(e.ref,e); else byRef.set(e.ref,{...e,...byRef.get(e.ref)}); });
          return Array.from(byRef.values()).sort((a,b)=>new Date(b.date).getTime()-new Date(a.date).getTime());
        });
      }catch{}
    })();
    return ()=>{cancelled=true;};
  },[isSignedIn]);

  // Un seul fetch de statut par commande récente (pas de polling en boucle ici —
  // le polling live GPS se fait dans la vue détail via ServiceTrackingView).
  useEffect(()=>{
    const THREE_H=3*60*60*1000;
    entries.forEach((e,i)=>{
      if(Date.now()-new Date(e.date).getTime()>THREE_H) return;
      fetch(`/api/orders/status/${e.ref}`,{cache:'no-store'})
        .then(r=>r.ok?r.json():null)
        .then(d=>{
          if(!d?.status) return;
          setEntries(prev=>{
            const next=[...prev];
            const idx=next.findIndex(x=>x.ref===e.ref);
            if(idx===-1) return prev;
            next[idx]={...next[idx],liveStatus:d.status,etaLabel:projectArrival(next[idx].date,d.status)??undefined};
            return next;
          });
        })
        .catch(()=>{});
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  },[]);

  const openEntry = entries.find(e=>e.ref===openRef);
  const openTheme = openEntry ? (ORDER_THEMES[openEntry.type as ServiceThemeKey] ?? ORDER_THEMES.eats) : null;

  const fmtDate=(iso:string)=>{
    try{const d=new Date(iso);return d.toLocaleDateString('fr-MA',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});}catch{return iso;}
  };

  const t=T[lang];
  const STATUS_LABEL:Record<string,string>={
    pending:t.statusPending, pending_payment:t.statusPendingPay, accepted:t.statusAccepted,
    preparing:t.statusPreparing, ready:t.statusReady, on_the_way:t.statusOnWay, on_way:t.statusOnWay,
    delivered:t.statusDelivered, completed:t.statusDelivered, cancelled:t.statusCancelled, refused:t.statusRefused,
  };

  return (
    <div style={{background:'#0a0a0a',minHeight:'100dvh',fontFamily:'system-ui,sans-serif'}}>
      <style>{`@keyframes mofadeIn{0%{opacity:0;transform:translateY(10px);}100%{opacity:1;transform:translateY(0);}}`}</style>
      {/* Header */}
      <div style={{background:'#111111',padding:'52px 20px 14px',borderBottom:'1px solid #2a2a2a',position:'sticky',top:0,zIndex:10,display:'flex',alignItems:'center',gap:12}}>
        <button onClick={()=>navigate('/')} style={{background:'none',border:'none',fontSize:20,cursor:'pointer',color:'#fff',padding:'4px 8px',display:'flex',alignItems:'center',justifyContent:'center',width:36,height:36,borderRadius:'50%',flexShrink:0}}>←</button>
        <div style={{flex:1}}>
          <p style={{fontSize:9,fontWeight:800,letterSpacing:'0.2em',color:'#9CA3AF',margin:'0 0 1px'}}>BRIDGE SAFI</p>
          <h1 style={{fontSize:'1.1rem',fontWeight:900,color:'#fff',margin:0}}>📦 {t.myOrdersTitle}</h1>
        </div>
        <span style={{fontSize:11,color:'#9CA3AF',fontWeight:700}}>{entries.length}</span>
        <button onClick={cycleLang} style={{width:34,height:34,borderRadius:'50%',border:'1px solid #2a2a2a',cursor:'pointer',background:'rgba(255,255,255,0.06)',display:'flex',alignItems:'center',justifyContent:'center',color:'#fff',fontSize:10,fontWeight:900,flexShrink:0}}>{MYORD_LANG_LABELS[lang]}</button>
        <button onClick={()=>navigate('/aide')}
          style={{display:'flex',alignItems:'center',gap:5,background:'rgba(37,211,102,0.15)',border:'1px solid rgba(37,211,102,0.4)',borderRadius:20,padding:'6px 12px',color:'#25D366',fontSize:11,fontWeight:800,cursor:'pointer',flexShrink:0}}>
          ❓ Aide
        </button>
      </div>

      {/* Content */}
      <div style={{padding:'16px',maxWidth:480,margin:'0 auto',boxSizing:'border-box' as const}}>
        {entries.length===0?(
          <div style={{textAlign:'center',padding:'80px 20px',animation:'mofadeIn 0.4s ease-out'}}>
            <div style={{fontSize:60,marginBottom:14}}>📭</div>
            <p style={{fontWeight:800,fontSize:17,color:'#fff',margin:'0 0 8px'}}>{t.myOrdersEmpty}</p>
            <p style={{color:'#9CA3AF',fontSize:13,margin:'0 0 28px'}}>{t.myOrdersEmptySub}</p>
            <button onClick={()=>navigate('/')} style={{padding:'12px 24px',borderRadius:14,border:'none',background:'linear-gradient(135deg,#065F46,#34D399)',color:'#fff',fontWeight:900,fontSize:14,cursor:'pointer'}}>
              {t.historyDiscover}
            </button>
          </div>
        ):entries.map((e,i)=>{
          const th=ORDER_THEMES[e.type as ServiceThemeKey]??ORDER_THEMES.eats;
          const isDelivered=e.liveStatus==='delivered'||e.liveStatus==='completed';
          return(
            <button key={i} onClick={()=>setOpenRef(e.ref)}
              style={{display:'block',width:'100%',textAlign:'left' as const,background:'#161616',borderRadius:16,padding:'14px 16px',marginBottom:10,border:'1px solid #2a2a2a',boxShadow:'0 2px 8px rgba(0,0,0,0.3)',animation:`mofadeIn 0.3s ease-out ${i*0.04}s both`,cursor:'pointer'}}>
              <div style={{display:'flex',alignItems:'center',gap:12,marginBottom:e.liveStatus?8:0}}>
                <div style={{width:42,height:42,borderRadius:12,background:th.accent+'22',display:'flex',alignItems:'center',justifyContent:'center',fontSize:21,flexShrink:0,border:`1px solid ${th.accent}44`}}>{th.icon}</div>
                <div style={{flex:1,minWidth:0}}>
                  <p style={{fontWeight:900,fontSize:14,color:'#fff',margin:'0 0 2px'}}>{th.label}</p>
                  <p style={{fontSize:10,color:'#9CA3AF',margin:0}}>{fmtDate(e.date)} · {e.ref}</p>
                </div>
                {(e.total??0)>0&&<p style={{fontWeight:900,fontSize:14,color:th.accent,margin:0,flexShrink:0}}>{e.total} DH</p>}
              </div>
              {e.liveStatus&&(
                <div style={{fontSize:11,fontWeight:700,borderRadius:10,padding:'8px 12px',display:'flex',alignItems:'center',justifyContent:'space-between',gap:6,background:'#0a0a0a',border:'1px solid #2a2a2a'}}>
                  <span style={{color:isDelivered?'#34D399':'#fff'}}>
                    {isDelivered?'✅ ':'⏱️ '}{STATUS_LABEL[e.liveStatus]??e.liveStatus}
                  </span>
                  {e.etaLabel&&<span style={{color:'#9CA3AF'}}>{t.myOrdersArrival} {e.etaLabel}</span>}
                </div>
              )}
            </button>
          );
        })}
      </div>

      {/* Détail plein écran — suivi GPS complet de la commande sélectionnée */}
      {openEntry&&openTheme&&(
        <div className="fixed inset-0 z-[90] overflow-y-auto" style={{background:'#0a0a0a'}}>
          <div style={{padding:'52px 16px 24px',maxWidth:480,margin:'0 auto'}}>
            <button onClick={()=>setOpenRef(null)} style={{background:'rgba(255,255,255,0.08)',border:'none',borderRadius:20,padding:'8px 16px',color:'#fff',fontSize:12,fontWeight:800,cursor:'pointer',marginBottom:16,display:'flex',alignItems:'center',gap:6}}>← Retour</button>
            <ServiceTrackingView orderRef={openEntry.ref} lang={lang} onNewOrder={()=>setOpenRef(null)} theme={openTheme}/>
          </div>
        </div>
      )}
    </div>
  );
}
function loadNav() {
  try {
    const raw=localStorage.getItem(NAV_KEY);
    if(!raw) return null;
    return JSON.parse(raw) as {lang:Lang;service:'none'|'delivery'|'taxi'|'taxi-select'|'moto'|'tabac'|'fleurs'|'pharmacie'|'boulangerie'|'souk'|'supermarche';page:Page;restaurantId:string|null};
  } catch { return null; }
}

export default function App() {
  const saved = loadNav();
  const { isLoaded, isSignedIn, user } = useUser();
  const [, navigate] = useLocation();

  // ── Dark mode ──────────────────────────────────────────────────────────────
  const [isDark, setIsDark] = useState<boolean>(() => {
    try { return localStorage.getItem(DARK_KEY) === '1'; } catch { return false; }
  });
  const toggleDark = useCallback(() => setIsDark(d => {
    const next = !d;
    try { localStorage.setItem(DARK_KEY, next ? '1' : '0'); } catch {}
    return next;
  }), []);
  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDark);
  }, [isDark]);

  const [lang,setLang]         = useState<Lang>(saved?.lang??'fr');
  const [page,setPage]         = useState<Page>(saved?.page??'home');
  // splashDone becomes true after 3s; we also wait for Clerk to load
  const [splashDone,setSplashDone] = useState(false);
  const [mode,setMode]             = useState<'hub'|'services'>('hub');
  const [service,setService]       = useState<'none'|'delivery'|'taxi'|'taxi-select'|'moto'|'tabac'|'fleurs'|'pharmacie'|'boulangerie'|'souk'|'supermarche'>(saved?.service??'none');
  const [cart,setCart]         = useState<CartItem[]>([]);
  const [showCart,setShowCart] = useState(false);
  const [showProfile,setShowProfile] = useState(false);
  const [showDriver,setShowDriver] = useState(false);
  const [lastOrderRef,setLastOrderRef] = useState<string>(()=>localStorage.getItem('bridge_last_ref')||'');
  const [selectedRestaurant,setSelectedRestaurant] = useState<Restaurant|null>(
    saved?.restaurantId ? (RESTAURANTS.find(r=>r.id===saved.restaurantId)??null) : null
  );
  const {profile,saveProfile}  = useProfile(user?.id);

  // Splash timer — 3 seconds
  useEffect(()=>{
    const t=setTimeout(()=>setSplashDone(true),1500);
    return()=>clearTimeout(t);
  },[]);

  // Track signed-in state for profile features; no forced redirect — app is open to all
  useEffect(()=>{
    if(!isLoaded) return;
    if(isSignedIn){
      try { localStorage.setItem('bridge_was_signed_in','1'); } catch {}
    }
  },[isLoaded,isSignedIn]);

  // Persist nav state on every relevant change
  useEffect(()=>{
    try {
      localStorage.setItem(NAV_KEY,JSON.stringify({
        lang, service, page,
        restaurantId: selectedRestaurant?.id ?? null,
      }));
    } catch {}
  },[lang,service,page,selectedRestaurant]);

  // ── Auto-sync Clerk user data → profile (email + name si vide) ──────────────
  useEffect(()=>{
    if(!user) return;
    const clerkEmail = user.primaryEmailAddress?.emailAddress || '';
    const clerkPhone = user.primaryPhoneNumber?.phoneNumber || '';
    const clerkName  = [user.firstName, user.lastName].filter(Boolean).join(' ');
    let updated = false;
    const patch: Partial<UserProfile> = {};
    if (clerkEmail && !profile.email) { patch.email = clerkEmail; updated = true; }
    if (clerkPhone && !profile.phone) { patch.phone = clerkPhone; updated = true; }
    if (clerkName  && !profile.name)  { patch.name  = clerkName;  updated = true; }
    if (updated) saveProfile({ ...profile, ...patch });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[user?.id]);

  const t=T[lang]; const isAR=lang==='ar'; const isAMZ=lang==='amz'; const fClass=fontClass(lang);
  const cycleLang=()=>setLang(l=>LANG_CYCLE[(LANG_CYCLE.indexOf(l)+1)%LANG_CYCLE.length]);

  const addToCart=(ci:CartItem)=>setCart(prev=>{
    const found=prev.find(x=>x.cartId===ci.cartId||
      (x.item.id===ci.item.id&&JSON.stringify(x.selectedOptions)===JSON.stringify(ci.selectedOptions)));
    if(found) return prev.map(x=>x.cartId===found.cartId?{...x,qty:x.qty+1}:x);
    return [...prev,ci];
  });

  const adjustQty=(cartId:string,delta:number)=>setCart(prev=>
    prev.flatMap(i=>{if(i.cartId!==cartId)return[i];const q=i.qty+delta;return q>0?[{...i,qty:q}]:[];})
  );

  const clearCart=()=>setCart([]);
  const cartCount=cart.reduce((s,i)=>s+i.qty,0);

  const handleSelectRestaurant=(r:Restaurant)=>{setSelectedRestaurant(r);setPage('restaurant');};
  const handleBack=()=>{setPage('home');setSelectedRestaurant(null);};

  const TABS:Page[]=['home','tracking','contact'];

  // ── Stable dark context value (must be before any conditional return) ──
  const dv = useMemo(() => ({ dark: isDark, toggle: toggleDark }), [isDark, toggleDark]);
  // Eats delivery → GPS tracking page
  const handleOrderSuccess=(ref:string)=>{setLastOrderRef(ref);setService('none');setPage('tracking');};
  // Tabac / Fleurs / Pharmacie → simple countdown tracking (no GPS map)
  const handleSimpleOrderSuccess=(ref:string)=>{setLastOrderRef(ref);setService('none');setPage('tracking');};

  // App is open to all — only block during initial animated splash (1.5s)
  // No sign-in wall: guests and signed-in users both access the app freely
  const isGuest = !isSignedIn;
  const showSplash = !splashDone;
  if(showSplash) return <SplashScreen/>;

  // Profile onboarding after first sign-in
  if(!profile.onboardingComplete) return (
    <DarkModeCtx.Provider value={dv}>
      <ProfileOnboardingScreen
        lang={lang}
        profile={profile}
        saveProfile={saveProfile}
        onDone={()=>saveProfile({...profile,onboardingComplete:true})}
      />
    <FloatingHelpWA/></DarkModeCtx.Provider>
  );

  if(mode==='hub') return <DarkModeCtx.Provider value={dv}><HubPage onServices={()=>setMode('services')} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile}/><PWAInstallBanner lang={lang}/><FloatingHelpWA/></DarkModeCtx.Provider>;

  const backToHub=()=>{setMode('hub');setService('none');};
  if(service==='none') return <DarkModeCtx.Provider value={dv}><ServiceSelectPage onSelect={s=>{if(s==='taxi')setService('taxi-select');else setService(s);}} onBack={backToHub} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile}/><PWAInstallBanner lang={lang}/><FloatingHelpWA/></DarkModeCtx.Provider>;
  if(service==='taxi-select') return <DarkModeCtx.Provider value={dv}><TaxiVehicleSelectPage onBack={()=>setService('none')} onSelect={v=>setService(v)} lang={lang} cycleLang={cycleLang}/><FloatingHelpWA/></DarkModeCtx.Provider>;
  if(service==='taxi') return <DarkModeCtx.Provider value={dv}><MotoTaxiPage vehicleType='taxi' onBack={()=>setService('taxi-select')} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile}/><FloatingHelpWA/></DarkModeCtx.Provider>;
  if(service==='moto') return <DarkModeCtx.Provider value={dv}><MotoTaxiPage vehicleType='moto' onBack={()=>setService('taxi-select')} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile}/><FloatingHelpWA/></DarkModeCtx.Provider>;
  if(service==='tabac') return <DarkModeCtx.Provider value={dv}><TabacPage onBack={()=>setService('none')} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile} onOrderSuccess={handleSimpleOrderSuccess}/><FloatingHelpWA/></DarkModeCtx.Provider>;
  if(service==='fleurs') return <DarkModeCtx.Provider value={dv}><FleurPage onBack={()=>setService('none')} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile} onOrderSuccess={handleSimpleOrderSuccess}/><FloatingHelpWA/></DarkModeCtx.Provider>;
  if(service==='pharmacie') return <DarkModeCtx.Provider value={dv}><PharmaciePage onBack={backToHub} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile} onOrderSuccess={handleSimpleOrderSuccess}/><FloatingHelpWA/></DarkModeCtx.Provider>;
  if(service==='boulangerie') return <DarkModeCtx.Provider value={dv}><BoulangeriePage onBack={()=>setService('none')} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile} onOrderSuccess={handleSimpleOrderSuccess}/><FloatingHelpWA/></DarkModeCtx.Provider>;
  if(service==='souk') return <DarkModeCtx.Provider value={dv}><SoukPage onBack={()=>setService('none')} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile} onOrderSuccess={handleSimpleOrderSuccess}/><FloatingHelpWA/></DarkModeCtx.Provider>;
  if(service==='supermarche') return <DarkModeCtx.Provider value={dv}><SupermarchePage onBack={()=>setService('none')} lang={lang} cycleLang={cycleLang} profile={profile} saveProfile={saveProfile} onOrderSuccess={handleSimpleOrderSuccess}/><FloatingHelpWA/></DarkModeCtx.Provider>;

  // Pill button style (shared between lang + profile)
  const pillStyle:React.CSSProperties={
    background:'var(--c-card)',border:'2.5px solid #D9C5A0',color:'#065F46',
    boxShadow:'0 4px 20px rgba(6,95,70,0.15)',height:'44px',minWidth:'44px',
  };

  return (
  <DarkModeCtx.Provider value={dv}>
    <div className={`min-h-screen overflow-x-hidden ${isAR?'rtl':'ltr'}`} style={{color:'var(--c-text)'}}>

      {/* ── Top-left: Back ── */}
      <div className={`fixed top-4 z-50 flex items-center gap-2 ${isAR?'right-4':'left-4'}`}>
        <button onClick={()=>setService('none')}
          className="flex items-center justify-center rounded-full transition-all active:scale-90"
          style={{...pillStyle, width:'42px', height:'42px', padding:0, fontSize:'18px'}}>
          ←
        </button>
      </div>

      {/* ── Top-right: Profile + Language ── */}
      <div className={`fixed top-5 z-50 flex items-center gap-2 ${isAR?'left-5':'right-5'}`}>
       {user ? ( 
    <button onClick={()=>setShowProfile(true)}
          className="rounded-full flex items-center justify-center font-black text-sm transition-all active:scale-90 hover:scale-110 relative"
          style={{...pillStyle,width:'44px',padding:0,overflow:'hidden'}}>
          {profile.avatar
            ?<img src={profile.avatar} alt="Profil" style={{width:'100%',height:'100%',objectFit:'cover',borderRadius:'50%'}}/>
            :<span style={{fontSize:'18px'}}>👤</span>
          }
          {profile.name&&<span className="absolute -top-1 -right-1 w-3 h-3 rounded-full border-2 border-white" style={{background:'#10B981'}}/>}
        </button>
        ) : (
  <button onClick={() => goToSignIn()}
    className="text-xs font-black px-3 py-1.5 rounded-full"
    style={{background:'#065F46',color:'white',border:'1px solid #D9C5A0'}}>
    {lang==='ar'?'تسجيل الدخول':lang==='amz'?'ⴰⴽⵛⵎ':'Se connecter'}
  </button>
)}
        <button onClick={cycleLang}
          className={`rounded-full flex items-center justify-center font-black text-sm transition-all active:scale-90 hover:scale-110 px-3 ${isAMZ?'font-tifinagh':''}`}
          style={{...pillStyle,fontSize:'13px'}}>
          {LANG_LABELS[lang]}
        </button>
        <DarkToggle/>
      </div>


      {/* ── Header ── */}
      <header className="relative pt-14 pb-4 flex flex-col items-center"
        style={{borderBottom:'1px solid var(--c-border)',background:'var(--c-nav-soft)',backdropFilter:'blur(14px)'}}>
        <div className="h-14 w-14 rounded-full overflow-hidden flex items-center justify-center flex-shrink-0"
          style={{border:'2.5px solid #D9C5A0',boxShadow:'0 4px 16px rgba(6,95,70,0.15)'}}>
          <img src="/logo.jpeg" alt="Bridge" className="w-full h-full object-cover" style={{transform:'scale(1.9)'}}/>
        </div>
        <h1 className="mt-2 text-[11px] font-black tracking-[0.45em] uppercase" style={{color:'#065F46'}}>
          {isAMZ?'ⴱⵔⵉⴷⵊ':isAR?'بريدج':'Bridge'}
        </h1>
        <p className={`text-[9px] tracking-widest mt-0.5 ${fClass}`} style={{color:'#B45309'}}>{t.zone}</p>
      </header>

      {/* ── Main content ── */}
      <main className="max-w-md mx-auto pt-5 pb-28">
        {page==='home'&&<HomePage lang={lang} t={t} onSelectRestaurant={handleSelectRestaurant}/>}
        {page==='restaurant'&&selectedRestaurant&&(
          <RestaurantPage restaurant={selectedRestaurant} lang={lang} t={t} onBack={handleBack} onAddToCart={addToCart}/>
        )}
        {page==='tracking'&&<TrackingPage lang={lang} t={t} orderRef={lastOrderRef}/>}
        {page==='simple-tracking'&&<SimpleTrackingPage orderRef={lastOrderRef} lang={lang} onNewOrder={()=>{setPage('home');setService('none');setMode('services');}}/>}
        {page==='contact'&&<ContactPage lang={lang} t={t}/>}
      </main>

      {/* ── Bottom nav (hidden on TV/large screens) ── */}
      <nav className="tv-hide-on-tv fixed bottom-0 inset-x-0 z-40"
        style={{background:'var(--c-nav)',backdropFilter:'blur(20px)',borderTop:'1px solid var(--c-border)'}}>
        <div className="max-w-md mx-auto flex">
          {([
            {id:'home' as Page,label:t.navHome,icon:'🏠'},
            {id:'tracking' as Page,label:t.navTrack,icon:'📍'},
          ]).map(tab=>(
            <button key={tab.id} onClick={()=>{setPage(tab.id);if(tab.id==='home')setSelectedRestaurant(null);}}
              className="flex-1 flex flex-col items-center gap-1 py-3 transition-all">
              <span className="text-xl transition-transform" style={{transform:page===tab.id&&!(page==='home'&&selectedRestaurant)?'scale(1.15)':'scale(1)'}}>{tab.icon}</span>
              <span className={`text-[10px] font-black uppercase tracking-wide ${fClass}`} style={{color:page===tab.id&&!(tab.id==='home'&&selectedRestaurant&&page==='restaurant')?'#065F46':'#9CA3AF'}}>{tab.label}</span>
              {page===tab.id&&tab.id!=='home'&&<div className="w-5 h-0.5 rounded-full" style={{background:'#065F46'}}/>}
              {tab.id==='home'&&page!=='restaurant'&&page==='home'&&<div className="w-5 h-0.5 rounded-full" style={{background:'#065F46'}}/>}
            </button>
          ))}
          {/* Panier — 3e onglet */}
          <button onClick={()=>setShowCart(true)}
            className="flex-1 flex flex-col items-center gap-1 py-3 transition-all active:scale-90 relative">
            <span className="text-xl relative">
              🛒
              {cartCount>0&&(
                <span className="absolute -top-1 -right-2 text-white text-[9px] font-black rounded-full w-4 h-4 flex items-center justify-center" style={{background:'#4F46E5'}}>{cartCount}</span>
              )}
            </span>
            <span className={`text-[10px] font-black uppercase tracking-wide ${fClass}`} style={{color:cartCount>0?'#4F46E5':'#9CA3AF'}}>
              {t.navCart||'Panier'}
            </span>
          </button>
        </div>
        <p className="text-center text-[9px] pb-2" style={{color:'#C9BFB2'}}>{t.footer}</p>
      </nav>

      <PWAInstallBanner lang={lang}/>
      {showCart&&<CheckoutDrawer cart={cart} lang={lang} onClose={()=>setShowCart(false)} onQty={adjustQty} profile={profile} saveProfile={saveProfile} onClearCart={clearCart} restaurantName={selectedRestaurant?.name} onOrderSuccess={ref=>{setLastOrderRef(ref);setPage('tracking');setShowCart(false);}}/>}
      {showProfile&&<ProfileModal lang={lang} profile={profile} onSave={saveProfile} onClose={()=>setShowProfile(false)}/>}

      {showDriver&&(
        <div className="fixed inset-0 z-50 flex items-end" style={{background:'rgba(10,30,20,0.7)',backdropFilter:'blur(6px)'}} onClick={()=>setShowDriver(false)}>
          <div className="w-full max-w-md mx-auto rounded-t-3xl p-6" style={{background:'var(--c-bg)',boxShadow:'0 -20px 60px rgba(0,0,0,0.3)'}} onClick={e=>e.stopPropagation()}>
            <div className="flex items-center gap-3 mb-5">
              <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-2xl" style={{background:'linear-gradient(135deg,#065F46,#047857)'}}>🛵</div>
              <div>
                <p className="font-black text-sm" style={{color:'#065F46'}}>Bridge Logistique</p>
                <p className="text-xs" style={{color:'#9CA3AF'}}>Portail livreurs · Tableau de bord</p>
              </div>
            </div>
            <p className="text-xs mb-4 leading-relaxed" style={{color:'#6B7280'}}>
              Accès réservé aux livreurs Bridge. Gérez vos livraisons, suivez vos commandes en temps réel.
            </p>
            <a href={DRIVER_APP_URL} target="_blank" rel="noopener noreferrer"
              className="block w-full py-3.5 rounded-2xl text-center font-black text-sm text-white"
              style={{background:'linear-gradient(135deg,#065F46,#047857)',boxShadow:'0 6px 20px rgba(6,95,70,0.3)'}}>
              Ouvrir l'app livreur →
            </a>
            <button onClick={()=>setShowDriver(false)} className="block w-full mt-3 py-3 rounded-2xl text-center text-xs font-bold" style={{color:'#9CA3AF',background:'#F3F4F6'}}>
              Fermer
            </button>
          </div>
        </div>
      )}
    </div>
  <FloatingHelpWA/></DarkModeCtx.Provider>
  );
}
